programs.sol:
"""Recognize a lexical contrast, rather than decide what a sentence means.

Foot spellings, footwear, and Chinese 足 (foot / sufficient) words predict
negative contributions. Rendering, declaring, handling, and registering
words predict positive ones. Case and code punctuation adjust a few scales.
The previous token identifies split compounds, resetting at document changes.
All other tokens predict zero: many weaker lexical responses are omitted.
"""
READS = ()

FOOT_WORDS = {
    'foot': -5.7, 'feet': -3.1, 'footing': -3.4, 'footprint': -2.6,
    'footprints': -1.7, 'footsteps': -1.5, 'footwear': -1.9,
    'footer': -1.8, 'footnote': -1.7, 'football': -1.2,
    'footage': -0.8, 'footh': -2.0, 'soccer': -1.0,
    'ankle': -1.4, 'ankles': -1.0, 'shoe': -1.0, 'shoes': -1.1,
    'sandals': -1.5, 'ft': -0.4, 'toe': -0.3, 'toes': -1.1,
    'heel': -0.6,
}
FOOT_CHARACTERS = {
    # Feet, legs, footwear, footprints, and football.
    '足': -9.4, '脚': -4.4, '腳': -4.8, '足球': -2.5,
    '中国足球': -2.4, '国足': -1.4, '足协': -0.7,
    '足迹': -1.9, '足跡': -1.9, '的脚步': -1.4,
    '腿': -0.5, '鞋': -0.9, '鞋子': -0.8, '袜': -0.7, '襪': -0.7,
    '一脚': -3.0, '手脚': -2.9, '双脚': -3.8,
    '脚下': -2.1, '脚步': -1.8, '蹄': -2.6, '趾': -1.3, '踝': -1.4,
    # Nonliteral 足 compounds: insufficient, sufficient, satisfied, foothold.
    '不足': -5.5, '不足以': -3.8, '充足': -1.9, '充足的': -0.7,
    '足够': -2.2, '足够的': -1.1, '有足够的': -0.4, '足以': -4.8,
    '满足': -1.2, '滿足': -1.2, '能满足': -1.4, '不够': -1.1,
    '立足': -3.0, '十足': -1.3, '足足': -3.8,
    # German foot/football, Russian leg stem, Korean foot character.
    'fuß': -1.8, 'fußball': -1.6, 'ног': -0.9, '족': -3.0,
}
DECLARING = {
    'declare': 3.2, 'declared': 2.4, 'declares': 2.5,
    'declaring': 2.3, 'declaration': 1.3, 'declarations': 1.5,
    'declar': 0.8, 'decl': 0.7, 'announce': 0.7, 'announced': 1.1,
    'announces': 1.1, 'announcing': 0.6,
    'announcement': 0.6, 'announcements': 0.6,
}
REGISTERING = {
    'register': 0.7, 'registered': 1.0, 'registering': 0.8,
    'registers': 0.6, 'registration': 0.5,
    'override': 0.5, 'overrides': 0.5,
}
RENDERING_AND_HANDLING = {
    'render': 2.0, 'renders': 2.0, 'rendered': 2.0, 'rendering': 2.0,
    'renderer': 1.3, 'handler': 1.5, 'handlers': 0.8, 'eventhandler': 1.3,
    # Chinese render, declare/announce, register, handle.
    '渲染': 2.3, '声明': 1.2, '宣': 1.5, '宣布': 1.1,
    '注册': 1.1, '处理': 0.5,
}
WORD_VALUES = (FOOT_WORDS | FOOT_CHARACTERS | DECLARING
               | REGISTERING | RENDERING_AND_HANDLING)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('._/-@')
    lower = word.lower()
    value = WORD_VALUES.get(lower, 0.0)

    if lower == 'foot':
        if word[0].isupper():
            value = -6.4
        if word.isupper():
            value = -4.3
        elif token.startswith(('-', '_')):
            value = -4.6
        elif previous.endswith('\\'):
            value = -4.1  # LaTeX footnote command.
    elif lower == 'ft' and not token[0].isspace():
        value = -0.07  # Glued suffix, rather than the length unit.
    elif lower == 'football':
        value = -1.4 if word[0].isupper() or token == 'football' else -1.1
    elif word == '足' and previous:
        # A preceding CJK character may have been split into UTF-8 byte tokens.
        before = prefix.text_prefixes[-1][:-1]
        if before.endswith(('満', '滿')):  # Satisfied.
            value = -5.2
        elif before.endswith(('補', '补', '驻', '駐', '具')):
            value = -6.8  # Supplement, stop, or possess.
        elif before.endswith('富'):  # Abundant.
            value = -5.4
    elif lower in ('render', 'renders', 'rendered', 'rendering'):
        value = 2.4 if word[0].isupper() else 2.0
        if token.startswith('.'):
            value = 2.4 if word[0].isupper() else 1.7
        elif not token[0].isspace() and word[0].islower():
            value = 1.7
    elif lower == 'renderer' and token.startswith(' ') and word[0].isupper():
        value = 1.9
    elif word == 'Handler':
        value = 1.8
    elif token == 'declare':
        value = 3.9
    elif token == ' Declare':
        value = 2.2
    elif token == ' Declaration':
        value = 0.75
    elif token.startswith('.') and lower == 'register':
        value = 1.2

    # Finish a foot or declaration compound split across two tokens.
    previous_word = previous.strip().lstrip('._/-').lower()
    if previous_word == 'foot':
        if token in ('note', 'notes', 'prints', 'steps'):
            value = -1.6
        elif token == 'ed':
            value = -2.8
    elif previous_word in ('de', 'dé'):
        if token == 'clare':
            value = 1.2 if previous.strip() == 'dé' else 2.7
        elif token in ('claration', 'clarations'):
            value = 0.9
    elif previous_word == 'decl' and token == 'ared':
        value = 1.1
    return (doc, token), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:4224: a lexical "foot" detector, with a few side meanings.

Reads the newest token's spelling, plus whether the token before was a foot word.

Strongly negative on the word for foot: "foot", "Foot", "-foot", "feet", "footing",
and the characters 足 and 脚 (Chinese and Japanese for foot). Moderately negative on
football, soccer, ankle and shoe, and on Chinese compounds with 足 (满足, 充足, 足够,
足球). Weakly negative on "footage", and on "note"/"notes" right after "Foot"
(as in "Footnotes"). Mildly positive on the verb stems declare, render, announce and
register, on "handler", and on the Chinese 渲染 (render), 声明 and 宣布 (declare, announce).
Everything else is about zero.
"""

READS = ()

FOOT_CHARS = {"足": -8.0, "脚": -4.5, "腳": -5.0, "족": -3.0}
SPORT_WORDS = ("football", "soccer", "ankle", "shoe")
POSITIVE_STEMS = (
    ("declar", 2.5), ("render", 2.0), ("渲染", 2.0), ("handler", 1.6),
    ("announc", 0.9), ("宣布", 1.0), ("声明", 1.3), ("regist", 0.8), ("注册", 1.0),
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if token.strip() in FOOT_CHARS:
        return carry, FOOT_CHARS[token.strip()]
    if any(s in word for s in SPORT_WORDS):
        return carry, -1.2
    if word == "footage":
        return carry, -0.8
    if word in ("note", "notes") and "foot" in previous:
        return carry, -1.6
    if "foot" in word:
        return carry, -4.5
    if word.startswith("feet"):
        return carry, -3.0
    if "足" in word:
        return carry, -2.5
    for stem, value in POSITIVE_STEMS:
        if stem in word:
            return carry, value
    return carry, 0.0

programs.sol:
"""Approximate a negative English adverb / auxiliary-ending response.

Adverbs are strongest after subject pronouns and modal auxiliaries, weaker
after 'be', conjunctions, and punctuation. Temporal adverbs, quantifiers,
and regular -ly endings use reduced versions of this pattern. 'Particularly'
gets a positive offset rather than behaving like a typical verb modifier.
Auxiliary contractions are negative; possessive 's' is mostly near zero.
Word offsets and shared strengths are rounded approximations fitted on
training data. Other small, token-specific responses are left at zero.
Only the newest token and two preceding tokens are used; documents reset state.
"""

READS: tuple[str, ...] = ()
SUBJECTS = set('i you he she we they'.split())
RELATIVES = set('it this that these those who which what there'.split())
MODALS = set('can could may might will would shall should must'.split())
BE = set('is are was were be been being'.split())
HAVE = set('have has had'.split())
PREPOSITIONS = set('of in on at with for from by as than into over under '
                   'through during without within before after until since'.split())
DETERMINERS = set('a an the my your his her our their its some any every no'.split())
LINKS = set('and or but if while although though because when where '
            'whether so then'.split())
TIME = set('then now soon once ever even almost too'.split())
QUANTIFIERS = set('all both each either neither first most more'.split())
OTHER_ADVERBS = set('alone itself themselves ourselves instead otherwise '
                    'further therefore hence thus yet again anymore anyway '
                    'somehow somewhat rather merely indeed well'.split())
LY_EXCEPTIONS = set('family supply apply reply multiply july italy daily '
                    'early friendly lovely lonely ugly assembly fly imply '
                    'rally belly holy comply'.split())
ADVERB_BASE = {
    'also': -0.49, 'just': -0.27, 'only': -0.15, 'still': -0.37,
    'always': -0.37, 'really': -0.26, 'never': 0.06,
    'probably': -0.43, 'usually': -0.23, 'often': -0.18,
    'already': 0.12, 'actually': -0.22, 'either': -0.49,
    'both': -0.22, 'otherwise': -0.18,
    'generally': -0.46, 'normally': -0.18, 'typically': -0.35,
    'definitely': -0.36, 'certainly': -0.16, 'truly': -0.17,
    'personally': -0.09, 'honestly': -0.19, 'possibly': 0.17,
    'surely': -0.09, 'apparently': 0.03, 'sometimes': 0.11,
    'seldom': -0.08, 'likewise': -0.01, 'throughout': 0.02,
    'directly': -0.18, 'efficiently': -0.12, 'accurately': 0.01,
    'properly': -0.07,
}


def context_strength(previous):
    """How strongly this preceding word supports a pre-verbal adverb."""
    p = previous.strip().lower()
    if p in SUBJECTS:
        return -1.95 if p == 'i' else -1.8
    if p in RELATIVES:
        return -1.0 if p == 'it' else -0.54
    if p in MODALS:
        return -1.32
    if p in BE:
        return 0.14
    if p in HAVE:
        return -0.42
    if p in {'do', 'does', 'did'}:
        return -0.32
    if p in {"'s", "'re", "'m", "'ve", "'ll", "'d", "'t"}:
        return -0.68
    if p == 'to':
        return -0.39
    if p in PREPOSITIONS or p in DETERMINERS:
        return 0.0
    if p in LINKS:
        return 0.07 if p == 'and' else 0.25
    if p in ADVERB_BASE or p.endswith('ly'):
        return -0.18
    if p == 'see':
        return 0.5
    if p.isalpha():
        return -0.13 if p.endswith(('ing', 'ed')) else -0.32
    return -0.3 if any(c.isdigit() for c in p) else 0.11


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, earlier = ('', '') if carry is None or carry[0] != doc else carry[1:]
    raw = prefix.token_strings[-1]
    state = (doc, raw, previous)
    word = raw.strip().lower().replace('’', "'")
    p = previous.strip().lower().replace('’', "'")
    curly = '’' in raw

    if word == "'s":
        value = -0.85 if p in {'he', 'she'} else {
            'it': -0.69, 'that': -0.34, 'what': -0.51,
            'there': -0.43, 'here': -0.16, 'who': -0.55,
        }.get(p, -0.02)
        return state, value - (0.06 if curly else 0.0)
    if word in {"'ve", "'ll", "'re", "'m", "'d"}:
        value = {"'ve": -1.14, "'ll": -0.87, "'re": -0.71, "'m": -0.36,
                 "'d": -1.85 if p in SUBJECTS else -0.77 if p in RELATIVES else -0.1}[word]
        return state, value - (0.16 if curly else 0.0)
    if word == "'t":
        value = {'don': -0.27, 'doesn': -0.03, 'didn': -0.12,
                 'can': -0.36, 'couldn': -0.29, 'won': -0.43,
                 'wouldn': -0.42, 'shouldn': -0.35, 'isn': 0.03,
                 'aren': -0.02, 'wasn': 0.0, 'weren': -0.04,
                 'haven': -0.27, 'hasn': -0.24, 'hadn': -0.32}.get(p, 0.0)
        if earlier.strip().lower() in SUBJECTS | RELATIVES:
            value -= 0.47
        if previous.strip()[:1].isupper() or not previous.startswith(' '):
            value += 0.28
        return state, value - (0.14 if curly else 0.0)
    if word == 'not':
        if p in BE or p in {'do', 'does', 'did'}:
            value = 0.0
        elif p in MODALS:
            value = -1.1
        elif p in SUBJECTS:
            value = -1.4
        elif p in RELATIVES:
            value = -0.85 if p == 'it' else -0.67
        elif p in {'or', 'if'}:
            value = 0.4
        elif p == 'to':
            value = -0.53
        elif p in LINKS or p in PREPOSITIONS or not p.isalpha():
            value = -0.2
        else:
            value = -0.43
        return state, value - (0.15 if raw.strip()[:1].isupper() else 0.0)
    if word in {'ly', 'ally', 'ously', 'ately'}:
        return state, -0.12

    strength = context_strength(previous.replace('’', "'"))
    if p in SUBJECTS | RELATIVES and previous.strip()[:1].isupper():
        strength -= 0.3
    if p in {'me', 'us', 'him', 'her', 'them'}:
        strength -= 0.3
    if word in QUANTIFIERS:
        value = ADVERB_BASE.get(word, -0.07) + 0.75 * strength
    elif word in ADVERB_BASE:
        value = ADVERB_BASE[word] + strength
    elif word in TIME:
        value = -0.07 + 0.7 * strength
    elif word in OTHER_ADVERBS:
        value = 0.03 + strength
    elif len(word) > 3 and word.isalpha() and word.endswith('ly') and word not in LY_EXCEPTIONS:
        value = -0.13 + 0.65 * strength
        if word == 'particularly':
            value += 0.4
        if p in MODALS:
            value -= 0.2
        if not raw.startswith(' '):
            value += 0.11
    else:
        value = 0.0
    return state, float(value)

programs.luna:
"""Give a small negative estimate for selected adverbs, negation, and clitics.

The additive words also, just, and only get the strongest response. Everything
else is left at zero; the estimate uses the current token and no history.
"""

READS = ()
SCALE = 0.37
EMPHASIS = {
    "also", "just", "only", "still", "ever", "first", "further",
    "soon", "already", "even", "really", "merely", "exactly",
}
MANNER = {
    "quickly", "directly", "fiercely", "clearly", "explicitly",
    "subsequently", "usually", "probably",
}
NEGATION = {"not", "never", "n't"}
CLITICS = {"'s", "'ve", "'d", "'t", "'re", "'ll", "'m"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in {"also", "just", "only"}:
        value = -1.7
    elif word in EMPHASIS:
        value = -0.9
    elif word in NEGATION or word in CLITICS:
        value = -0.8
    elif word in MANNER:
        value = -0.65
    else:
        value = 0.0
    return None, SCALE * value

programs.sol:
"""Detect mathematical and programming operators, not ordinary punctuation.

The strongest responses are to multiplication, addition, comparison, powers,
roots, and mathematical function names. Operators attached to parentheses or
one-letter variables are treated as parts of expressions. For ambiguous signs,
use preceding operands and decaying counts of math signs, digits, and code
markers. Line starts and whitespace help separate expressions from comments,
lists, and diff markers. Also recognize membership in a loop or condition,
a few LaTeX relations, and type/redirect operators. The numbers are calibrated
from training activations; token-specific baseline fluctuations are not modeled.
State resets at each document boundary.
"""
import re

READS = ()
FUNCTIONS = {'sqrt', 'sin', 'cos', 'tan', 'log', 'ln', 'mod', 'pow'}
MATH_SIGNS = set('+*^²³√×≤≥≡≈')
SYMBOL_LEVEL = {
    '²': 0.90, '³': 0.42, '√': 1.83, '×': 1.03, '÷': 0.83,
    '−': 0.67, '±': 0.72, '≤': 1.22, '≥': 1.22, '≠': 0.91,
    '≈': 0.84, '≡': 1.02, '∂': 0.93, '∈': 0.77, '⊢': 0.58,
    '⇒': 0.26, '→': 0.18, 'π': 0.36, '·': 0.11,
    '&&': 0.81, '||': 0.58, '<<': 1.07, '>>': 0.13, '>&': 0.51,
    '+=': 1.11, '-=': 1.11, '*=': 1.11, '/=': 1.11,
    '++': 0.12, '--': 0.02, '=>': -0.10,
    '(-': 0.63, '[-': 0.63, ',-': 0.63,
    ')(': 0.32, '][': 0.32,
}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0.0, 0.0, 0.0)
    # Decaying counts summarize context; tail is only the last 160 characters.
    _, previous, tail, math_count, code_count, digit_count = carry
    t = s.strip()
    spaced = s.startswith(' ')
    math = min(math_count / 4, 1)
    code = min(code_count / 4, 1)
    numbers = min(digit_count / 4, 1)
    word = previous.strip()
    after_number = bool(word) and (word[-1].isdigit() or word[-1] in ')]}²³')
    after_variable = word.isalpha() and (len(word) == 1 or word == 'pi'
                                        or (len(word) == 2 and word.isupper()))
    identifier = bool(re.fullmatch(r'[a-zA-Z_]\w*', word))
    after_bracket = bool(word) and word[-1] in ')]}'
    whitespace = bool(tail) and tail[-1].isspace()
    line = tail.replace('\\n', '\n').replace('\\t', '\t').rsplit('\n', 1)[-1]
    line_start = bool(re.fullmatch(r'(?:\s*\d+\t)?\s*', line))

    value = SYMBOL_LEVEL.get(t, 0.0)
    if t in {'==', '!=', '===', '!==', '<=', '>='}:
        value = {'==': 1.62 if spaced else 0.96,
                 '!=': 1.33, '===': 1.31 if spaced else -0.24,
                 '!==': 1.43, '<=': 1.72, '>=': 1.72}[t]
    elif t == '+':
        value = (1.32 - 0.66*code + 0.43*math - 0.85*whitespace if spaced
                 else 0.91 - 0.96*line_start + 0.49*math + 0.27*numbers)
    elif t == '-':
        value = (0.09 + 0.91*math + 0.45*numbers + 0.32*after_variable if spaced
                 else 0.01 + 0.83*math + 0.06*after_variable)
    elif t == '*':
        value = (0.78 - 1.02*whitespace + 0.68*after_number + 0.26*after_variable
                 if spaced else 0.69 + 1.12*after_number - 0.70*line_start
                 + 0.28*after_variable)
    elif t == '/':
        value = (-0.04 + 0.77*after_number + 1.02*math + 0.19*identifier if spaced
                 else 0.52*after_number + 0.87*math + 0.34*after_variable)
    elif t == '=':
        value = (0.02 if spaced else 0.17) + 0.45*math
        value += 0.38*after_variable + 0.35*after_number
    elif t == '<':
        value = (0.24 + 0.81*after_variable - 0.65*whitespace + 0.69*after_number
                 if spaced else 0.18)
    elif t == '>':
        value = 0.96 if spaced else 0.10
    elif t in {'?', '??'}:
        value = (0.35 if t == '?' else 0.42) if spaced else 0.02
    elif t in {'–', '~'}:
        value = (0.65 if t == '–' else 0.50)*math
    elif t == '^':
        value = (0.47 if spaced else
                 0.73 + 0.34*math - 0.24*after_bracket + 0.22*numbers)
    elif t == '[':
        value = 0.09 + 0.43*math - 0.11*whitespace + 0.12*after_number
    elif t in {'**', '&', '%'}:
        value = {'**': 0.02 if spaced else 0.25, '&': 0.15, '%': 0.12}[t]
    else:
        name = t.lstrip('(.').lower()
        if name in {'in', 'ge', 'le', 'to'} and tail.endswith('\\'):
            value = {'in': 0.49, 'ge': 0.67, 'le': 0.67, 'to': 0.40}[name]
        elif name == 'in':
            # A simple identifier/index expression following a code control word.
            clause = re.search(
                r'\b(for|if|elif|while)\s+[\w.]+(?:\[[^\]]*\])?\s*$', line)
            starts_clause = re.match(r'\s*(?:\d+\t)?(for|if|elif|while)\b', line)
            value = 0.84 if clause and (code > 0.04 or starts_clause) else 0.0
        elif name in {'extends', 'instanceof'}:
            value = 0.55 if name == 'extends' else 0.80
        elif name in {'floor', 'abs'}:
            value = (0.60 if name == 'floor' else 0.38) if math > 0.05 else 0.10
        elif name in {'sin', 'cos', 'sinh', 'cosh'}:
            value = (0.94 + 0.84*math - 0.27*identifier + 0.31*numbers if spaced
                     else 1.13 + 0.90*math - 0.54*identifier - 0.39*line_start)
        elif name == 'mod':
            value = (0.69 + 0.72*after_number + 0.47*math
                     + 0.17*after_variable) if spaced else 0.25
        elif name in {'sqrt', 'tan', 'tanh', 'ln', 'log', 'pow', 'cdot', 'times'}:
            value = {'sqrt': 1.47, 'tan': 0.62, 'tanh': 0.62, 'ln': 0.68,
                     'log': 0.51 if spaced else 0.23, 'pow': 0.25,
                     'cdot': 0.43, 'times': 0.15}[name]
        elif name == 'pi':
            value = 0.42 + 0.79*math + 0.33*after_number - 0.20*identifier
        elif re.fullmatch(r'[)\]}]+[+*/=^-][({\[\\-]*', t):
            operator = t.lstrip(')]}')[0]
            value = {'+': 1.13, '-': 0.57, '*': 1.79, '/': 1.28,
                     '=': 0.85, '^': 1.33}[operator]
        elif re.fullmatch(r'[+*/=^-](?:[a-zA-Z]|pi|sin|cos|sqrt|sizeof|[(\\{-]+)', t):
            operator = t[0]
            value = {'+': 1.10, '-': 0.0, '*': 1.64, '/': 0.10,
                     '=': 0.58, '^': 0.70}[operator]
            if operator == '/' and t[1].isalpha():
                value = 0.02 + 0.52*math + 0.26*after_number + 0.15*after_variable
            elif operator == '/':
                value = 0.99
            elif operator == '*' and not t[1].isalpha():
                value = 0.62 + 1.31*after_number + 0.82*after_variable - 0.79*whitespace
            elif operator == '-':
                value = -0.03 + 0.52*math + 0.15*after_number
        elif re.fullmatch(r'[₀-₉⁰-⁹⁻]+', t):
            value = 0.15
        elif len(t) >= 3 and len(set(t)) == 1 and t[0] in '+-=^':
            value = {'+': -1.06, '-': 0.0, '=': -0.09, '^': -0.26}[t[0]]

    # A sign fused with a newline is usually formatting, not an operator.
    if '\n' in s and t in set('+-*/=<>^'):
        value = (-0.23 if not spaced else 0.45) if t == '+' else 0.0
    strong_math = t in MATH_SIGNS or t in FUNCTIONS
    strong_math |= len(t) <= 3 and bool(re.search(r'[+*^]', t))
    math_count = 0.94*math_count + (strong_math and not line_start)
    code_count = 0.94*code_count + (t in {';', '{', '}', 'def', 'const',
                                         'return', 'let', 'import', 'public', 'void'}
                                        or '"' in t)
    digit_count = 0.94*digit_count + t.isdigit()
    if '\n' in s or '\\n' in s:
        previous = s.replace('\\n', '\n').rsplit('\n', 1)[-1]
    elif t:
        previous = s
    carry = (doc, previous, (tail+s)[-160:], math_count, code_count, digit_count)
    return carry, float(value)

programs.haiku:
"""Arithmetic and relational operator symbols, inside math text.

Layer-0 MLP feature for math formulas: it fires on the operator tokens of
equations and code expressions (+, *, ^, sqrt, ==, !=, <, -, /, =), with the
strength depending on the kind of operator, and is scaled up when the nearby
tokens (the last 12 in the same document) are mostly math characters (digits,
single letters, operator symbols). It is near zero on ordinary prose and on
other tokens.
"""
READS = ()

FUNCS = {"√", "sqrt", " sqrt", "sin", " sin", "cos", " cos", "tan", " tan", "log", " log", "mod", " mod"}
EQUAL_CMP = {"==", " ==", "===", " ===", "!=", " !=", "!==", " !==", "≠", "≈"}
ORDER_CMP = {"<=", " <=", ">=", " >=", "≤", "≥", "<<", " <<", ">>", " >>", " <", " >", "<", ">"}
POWER = {"^", "²", "³", " ^"}
LOGIC = {"&&", " &&", "||", " ||"}

def is_math(s):
    s = s.strip()
    if not s:
        return False
    if s.isdigit():
        return True
    if len(s) == 1 and s.isascii() and s.isalpha():
        return True
    return all(c in "+-*/^=()<>[]{}|√²³×·≤≥≠" for c in s)

def weight(s):
    st = s.strip()
    if st in ("+", "+="):
        return 1.2
    if s in FUNCS or st in FUNCS:
        return 1.1
    if s[:1] == ")" and any(c in s for c in "+-*/^=<>"):
        return 1.0
    if "*" in s and st != "**":
        return 0.9
    if st in POWER:
        return 0.8
    if s in EQUAL_CMP or st in EQUAL_CMP:
        return 1.3
    if s in ORDER_CMP or st in ORDER_CMP:
        return 0.5
    if st in LOGIC:
        return 0.8
    if st == "**":
        return 0.3
    if st in ("=", " ="):
        return 0.3
    if s == " -":
        return 0.4
    if st in ("-", "/", " /"):
        return 0.2
    return 0.0

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    t = prefix.position
    w = weight(s)
    if w == 0.0:
        return None, 0.0
    lo = max(0, t - 12)
    ctx = [prefix.token_strings[i] for i in range(lo, t)
           if prefix.document_ids[i] == prefix.document_ids[t]]
    dens = sum(is_math(c) for c in ctx) / len(ctx) if ctx else 0.0
    return None, float(w * (0.5 + dens))

