programs.sol:
"""A negative pulse for minus-ending punctuation and, more weakly, equality.

Opening brackets and operators before a terminal minus amplify the pulse;
closing brackets and leading spaces weaken it. Bare hyphens distinguish
list starts, numeric ranges, and word joins. Equals is more negative after
numbers or short variables than after named words. Words and dash rules
are otherwise left at zero; smaller lexical responses are not modeled.
"""
READS = ()
# Familiar classes of punctuation immediately preceding a minus sign.
MINUS_PRECEDERS = (
    (')]}', -1.3),       # closing brackets
    ('\\', -1.1),        # escape character
    ('[', -3.9),        # opening square bracket
    ('/|;', -4.3),      # division, vertical bar, semicolon
    ('*%+', -3.55),     # arithmetic operators
    ('.', -2.25),       # period
    ('({', -2.9),       # other opening brackets
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    mark = token.strip()
    if not mark or '\n' in token or any(c.isalnum() for c in mark):
        return None, 0.0
    spaced = token.startswith(' ')
    prev = ''
    if prefix.position and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
    word = prev.strip()
    value = 0.0
    if mark == '-':
        if not prev:
            value = -.78 if spaced else -1.75
        elif spaced:
            value = -.35 if word.isdecimal() else -.44
        elif prev.endswith('\n'):
            value = -.51
        else:
            value = -.65 if word.isdecimal() else -.95
    elif mark.endswith('-') and not mark.startswith('<!--'):
        head = mark[:-1]
        if set(head) == {'-'}:
            value = 0.0
        elif head.endswith('-'):
            value = -1.0
        else:
            value = -2.7
            for chars, strength in MINUS_PRECEDERS:
                if head[-1] in chars:
                    value = strength
                    break
            if head[-1] in '({':
                value += .4 * ('^' in head) - .55 * ('*' in head)
            value += .55 * spaced
    elif mark == '=':
        if word.isdecimal() or len(word) <= 2 or not word.isalpha():
            value = -.34 if spaced else -.38
        else:
            value = .02 if spaced else -.17
    elif len(mark) == 2 and mark.endswith('='):
        operator = mark[0]
        if operator in ')]}':
            value = -.62
        elif operator in '+-*/&|':
            value = -1.05 if operator == '+' else -1.5
        elif operator == ':':
            value = -.38 if spaced else -.70
        elif operator == '>':
            value = -.61 if spaced else -1.0
        elif operator in '<!':
            value = -.23 if operator == '<' else -.20
    elif mark.endswith('->'):
        value = -.21 if '-->' in mark else (-.56 if spaced else -.33)
    elif mark == '−':
        value = -.14 if spaced else -.26
    elif mark == '‐':
        value = -.63
    return None, float(value)

programs.haiku:
"""layers.0.mlp.down_proj:4228, a "minus / equals sign" detector.

What it does: this component writes a negative value into the residual stream at
tokens that are a minus sign or an equals sign used as an operator, in maths, code,
or shell text. The strength depends on the form of the token:

  * a standalone "-" (or "‐", or "->") is about -0.8 (or -0.4 when it has a leading
    space, " -", which is also common after numbers and code words);
  * a minus glued directly onto a preceding bracket or punctuation mark
    ("(-", ",-", "[-", "*(-", "=-", ...) is the strongest, about -2.9; glued after a
    closing bracket (")-", "}-") it is about -1.2;
  * "=" is about -0.3, and " =" about -0.16;
  * everything else, including hyphens inside words ("well-known") and "--", is 0.

It only reads the newest token, so it has no carry state.
"""

import re

READS = ()

OPEN_GLUED = re.compile(r"[(\[{,;:=/|*^.`'\"]+-")
CLOSE_GLUED = re.compile(r"[)}\]]+-")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    w = tok.lstrip(" ")
    if tok == " -":
        return None, -0.41
    if w in ("-", "‐"):
        return None, -0.76
    if w == "->":
        return None, -0.5
    if OPEN_GLUED.fullmatch(w):
        return None, -2.9
    if CLOSE_GLUED.fullmatch(w):
        return None, -1.2
    if tok == " =":
        return None, -0.16
    if w == "=":
        return None, -0.33
    return None, 0.0

programs.sol:
"""English subject/auxiliary patterns, with a two-token memory.

Modals and perfect auxiliaries respond positively, especially following
'it/this/that', 'what', or existential 'there'. Copulas often respond
negatively in those constructions. A weaker response persists onto 'be'
and articles. Infinitival 'to' and some negation contractions have
short-range subject effects too. Split locative compounds are also positive.
Document-initial 'what/there' have distinct responses. Memory resets at
document boundaries; unhandled tokens are approximated by zero.
"""
READS = ()

# Fitted response away from a pronoun, then strength of the subject effect.
POSITIVE = {
    'can': (0.05, 1.30), 'could': (0.40, 1.10),
    'may': (0.74, 1.10), 'might': (0.68, 0.90),
    'must': (0.74, 1.20), 'should': (0.81, 1.05),
    'will': (0.30, 0.90), 'would': (0.55, 0.90),
    'shall': (0.56, 0.50), "'ll": (0.50, 2.20),
    'has': (-0.05, 0.90), 'have': (-0.05, 0.90),
    'had': (-0.10, 1.00), 'does': (-0.07, 0.70),
    'did': (0.0, 1.0), 'do': (-0.07, 0.70),
    'need': (-0.10, 0.80), 'needs': (-0.08, 0.90),
    'ought': (0.05, 0.78), 'to': (0.0, 0.32),
}
SUBJECT = {
    'it': 1.10, 'this': 1.15, 'that': 0.90, 'what': 1.80,
    'there': 3.00, 'which': 0.65, 'who': 0.40, 'they': 0.35,
    'he': 0.18, 'she': 0.18, 'i': 0.10,
}
COPULA = {
    'it': -1.60, 'this': -0.15, 'that': -0.67,
    'what': -2.68, 'there': -1.06, 'who': -0.19, 'which': -0.08,
    'here': -0.40, 'where': -0.49,
}
MODALS = {'can', 'could', 'may', 'might', 'must', 'should',
          'will', 'would', 'shall', "'ll"}
LOCATIVE_COMPOUNDS = {
    'hereafter': 1.05, 'thereafter': 2.80, 'therefrom': 2.35,
    'thereupon': 2.50, 'whereabouts': 1.40, 'hereunder': 0.52,
    'hereof': 0.60, 'herein': 0.64, 'therein': 1.70,
    'thereon': 1.80, 'thereof': 2.00,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = not carry or carry[0] != doc
    previous, before = ('', '') if fresh else carry[1:]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower().replace('’', "'").lstrip('.,:;!?')
    subject = SUBJECT.get(previous, 0.0)
    value = 0.0
    if word in POSITIVE:
        base, scale = POSITIVE[word]
        value = base + scale * subject
        if word == 'will' and previous in {'you', 'we'}:
            value += 0.14
        if word == 'do' and previous == 'what':
            value = 2.32
        if word in {'have', 'need'} and previous in MODALS:
            value = 1.10 * POSITIVE[previous][0]
            value += 0.70 * SUBJECT.get(before, 0.0)
        if word == 'to':
            if previous == 'there':
                value = 1.95
            elif previous in {'need', 'needs', 'has', 'ought'}:
                value = 0.70 if previous == 'ought' else 0.18
                value += 0.70 * SUBJECT.get(before, 0.0)
        if raw.strip()[:1].isupper():
            value = {'may': 0.21, 'can': 0.10}.get(word, base)
    elif word in {'is', 'was', 'were', 'are'}:
        scale = {'is': 1.0, 'was': 0.52, 'were': 0.32, 'are': 0.78}[word]
        value = scale * COPULA.get(previous, 0.0)
        if word == 'are' and previous != 'what':
            value = 0.33 * COPULA.get(previous, 0.0)
        if word == 'is' and previous == 'what':
            capital = prefix.token_strings[-2].strip()[:1].isupper()
            value = -2.82 if capital else -2.35
        if previous == 'there' and word != 'is':
            value = {'was': 0.12, 'were': 0.52, 'are': -0.22}[word]
        if previous in {'you', 'we'}:
            value = 0.34 if word == 'are' else 0.20
        if previous == 'this' and word != 'is':
            value = 0.12
    elif word == "'s":
        value = {'it': -1.47, 'what': -1.52, 'that': -0.72,
                 'he': -0.42, 'she': -0.42, 'let': 0.60,
                 'where': -0.53, 'here': 0.15, 'who': -0.45
                 }.get(previous, 0.03)
    elif word in {"'m", "'re"}:
        value = -0.37 if previous == 'they' else -0.13
    elif word in {"'ve", "'d"}:
        value = 0.12 + SUBJECT.get(previous, 0.0)
    elif word == "'t":
        value = 0.03
        if previous in {'can', 'don', 'doesn', 'won', 'wouldn', 'shouldn'}:
            value = 0.05 + 0.65 * SUBJECT.get(before, 0.0)
            if previous in {'won', 'wouldn', 'shouldn'}:
                value += 0.20
    elif word == 'me' and previous == 'let':
        value = 0.84
    elif word in {'be', 'been'}:
        value = -0.05
        if previous in MODALS or previous in {'has', 'have', 'had'}:
            if before != 'there':
                value += 0.38 * COPULA.get(before, 0.0)
    elif word in {'the', 'a', 'an', 'no'}:
        if previous in {'is', 'are', 'was', 'were', "'s"}:
            value = 0.16 * COPULA.get(before, 0.0)
            if before == 'what':
                value *= 2.0
        elif word == 'the' and previous in {'what', 'that'}:
            value = -0.53 if previous == 'what' else -0.13
    if previous in {'here', 'there', 'where'} and not raw[:1].isspace():
        value = LOCATIVE_COMPOUNDS.get(previous + word, value)
    if fresh and word in {'what', 'there'}:
        if raw in {'What', 'There'}:
            value = 4.18 if word == 'what' else 3.11
        elif raw.strip()[:1].isupper():
            value = 2.78 if word == 'what' else 2.44
        else:
            value = 1.70 if word == 'what' else 2.00
    return (doc, word, previous), float(value)

"""A formatting-control response: negative tabs, positive bare carriage returns.

Single-tab tokens respond much more strongly than paired tabs. Their
response is conditioned on whether the preceding token ends a line, ends
in tabs, or is a number. Except at the very first token, it weakens farther
into the document. Bare carriage returns respond positively, especially
when they dominate the prefix. Other tokens get a small background value.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, carriage_returns = 0, '', 0
    else:
        _, position, previous, carriage_returns = carry
    token = prefix.token_strings[-1]
    carriage_returns += token == '\r'
    value = 0.0025
    if token == '\t':
        if position == 0:
            value = -0.39
        elif previous.endswith('\t'):
            value = -0.43 - 0.08 * math.exp(-position / 300)
        elif previous.endswith('\n'):
            value = -0.60 - 0.14 * math.exp(-position / 100)
        elif previous.isdigit():
            value = -0.56 - 0.10 * math.exp(-position / 50)
        else:
            value = -0.60 - 0.15 * math.exp(-position / 20)
    elif token == '\t\t':
        value = -0.11
    elif token == '\r':
        frequency = carriage_returns / (position + 1)
        value = 0.07 + 1.18 * frequency ** 3
    return (doc, position + 1, token, carriage_returns), value

