programs.sol:
"""A graded lexical detector of pinning down information.

The largest responses are to 'determine' and 'figure out'; related
calculation, identification, discovery and decision families are weaker.
Past tenses and related nouns usually get reduced gains. Selected translated
forms are included. Carry joins split words, recognizes phrasal verbs across
pronouns, and adds a brief echo on following articles/prepositions. It resets
at document boundaries. Unlisted words receive zero, except for a small
response to the reasoning tag '<think>'.
"""
import re

READS = ()
LETTERS = re.compile(r'[^\W\d_]+')
# Graded families: calculation/identification, decisions/discovery,
# knowledge gain, conclusions/recognition, demonstration.
FAMILIES = (
    ('calculat comput identif detect', 1.25),
    ('decid resolv establish discover', 1.00),
    ('learn predict indicat assess', 0.75),
    ('solv conclud recogniz recognis reveal', 0.50),
    ('distinguish retriev', 0.63),
    ('ascertain', 2.47),
    ('demonstrat', 0.40),
)
STEMS = [(s, gain) for family, gain in FAMILIES for s in family.split()]
ENDINGS = {'', 'e', 'y', 's', 'es', 'ies', 'ing', 'ed', 'ied', 'ying',
           'er', 'ers',
           'ation', 'ations', 'ication', 'ications', 'ion', 'ions',
           'ment', 'ments', 'ery', 'eries'}
CHINESE = {
    '确定': 2.55, '確定': 2.55, '决定': 1.55, '決定': 1.55,
    '判断': 1.20, '判斷': 1.20, '决': 1.00, '決': 1.00,
    '定': 0.48, '断': 0.65, '斷': 0.65,
    '识别': 1.00, '識別': 1.00, '出来': 0.83, '出來': 0.83,
    '找出': 0.90, '找到': 0.32, '计算': 0.74, '計算': 0.74,
    '预测': 0.64, '預測': 0.64, '判定': 0.69,
}


def gain(word):
    if word == 'new':
        return 0.20
    if word in {'outcome', 'outcomes'}:
        return 0.62
    if word == 'deduce':
        return 1.90
    if word in {'comput', 'computer', 'computers'}:
        return 0.0
    if word.startswith('predetermin'):
        return 1.80
    if word.startswith('determin'):
        ending = word[8:]
        if ending in {'e', 'ing'}:
            return 4.70
        if ending in {'ed', 'ation', 'ations'}:
            return 3.20
        if ending == 'es':
            return 3.60
        if not ending:
            return 2.80
        if ending in {'ant', 'ants'}:
            return 0.73
        if ending in {'istic', 'ism'}:
            return 1.10
        if ending in {'ar', 'are'}:
            return 3.00
        if ending in {'ado', 'ada', 'ados', 'adas'}:
            return 2.55
        if ending in {'ación', 'azione'}:
            return 1.50
        return 0.0
    if word.startswith(('undetermin', 'indetermin', 'nondetermin', 'détermin')):
        return 2.20
    if word.startswith('определ'):
        return 2.50 if word.endswith('ить') else 1.55
    for stem, value in STEMS:
        if word.startswith(stem) and word[len(stem):] in ENDINGS:
            if word.endswith(('ed', 'ied')):
                return value * 0.65
            if word.endswith(('ion', 'ions', 'ment', 'ments', 'ery', 'eries')):
                return value * 0.60
            return value
    if word in {'identifier', 'identifiers'}:
        return 1.35
    if word.startswith(('decisi', 'conclus', 'recognit', 'resolu')):
        return 0.50
    if word in {'find', 'finds', 'figure', 'figures', 'figured', 'figuring',
                'tell', 'tells', 'telling'}:
        return 0.43
    if word in {'finding', 'found'}:
        return 0.15
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', 9)
    _, tail, previous, verb, distance = carry
    token = prefix.token_strings[-1]
    words = LETTERS.findall(token)
    word = words[-1].lower() if words else ''
    if words and token[0].isalpha() and not words[-1].isupper() and gain(word) == 0:
        word = (tail + word)[-48:]
    value = gain(word)
    if words and words[-1][0].isupper() and value > 1:
        value *= 1.15 if word == 'determin' else 0.90
    if word in {'see', 'know'}:
        value = 0.55 if previous == 'to' else 0.08
    if word == 'out':
        value = -0.26 if token.startswith('.') else 0.20
        if distance <= 2:
            if verb.startswith('figur'):
                value = 5.60 if distance == 0 else 4.10
            elif verb in {'find', 'finds', 'finding', 'work', 'works', 'working'}:
                value = 3.00
            elif verb in {'found', 'worked'}:
                value = 2.20
            elif verb.startswith(('point', 'carri')) or verb == 'carry':
                value = 1.00
            elif verb.startswith(('check', 'turn', 'stand')):
                value = 0.65
            elif verb in {'lay', 'laid', 'rule', 'ruled'}:
                value = 1.45
    before = gain(previous)
    if word == 'the':
        value += min(1.20, before * 0.48)
        if previous in {'find', 'finds'}:
            value += 0.15
    elif word == 'of' and previous.endswith(('ation', 'ations')):
        value += before * 0.42
    elif word in {'by', 'to', 'that'} and previous.startswith('determin'):
        value += before * 0.24
    value = CHINESE.get(token.strip().removesuffix('了'), value)
    if token == '<think>':
        value = 0.23
    distance += 1
    if word and word not in {'it', 'this', 'that', 'them', 'things'}:
        verb, distance = word, 0
    if not words and token.strip():
        verb, distance = '', 9
    tail = word if token and token[-1].isalpha() else ''
    return (doc, tail, word, verb, distance), float(value)

programs.haiku:
"""Verbs of determining: the component fires on words meaning "to find out or settle a
fact or answer": "determine" most strongly, then the "-ed" and noun forms, then verbs such as
"identify", "calculate", "compute", "detect", "decide", "discover", "establish", "resolve".
Subword pieces are joined back into whole words, so a word split across tokens still counts
on the token where it is recognised. "out" after "figure", "find" or "work" (as in "figure
out") is strong too."""
READS = ()

DETERMINE_NOW = {"determine", "determining"}
DETERMINE_OTHER = {"determines", "determined", "determination"}
RESOLVE = {"identify", "identifies", "identified", "identifying", "calculate", "calculates",
           "calculated", "calculating", "compute", "computes", "computed", "computing",
           "detect", "detects", "detected", "detecting", "decide", "decides", "decided",
           "discover", "discovers", "discovered", "establish", "established", "establishes",
           "resolve", "resolves", "resolved", "solve", "solved", "predict", "predicted",
           "learn", "learned", "ascertain", "conclude", "concluded"}
FIND_VERBS = {"figure", "figured", "figuring", "find", "found", "finding", "work", "worked"}
WEAK = {"find", "figure", "decision", "decisions", "determinant", "indicate", "indicated", "assess"}


def step(carry, prefix, upstream):
    # carry: (previous whole word, current word so far); reset at each new document.
    fresh = carry is None or prefix.position == 0 or (
        prefix.document_ids[-1] != prefix.document_ids[-2])
    prev, cur = ("", "") if fresh else carry
    tok = prefix.token_strings[-1]
    piece = tok.strip().lower()
    if tok[:1] == " " or not tok[:1].isalpha():
        prev, cur = cur, (piece if piece.isalpha() else "")
    else:
        cur = cur + piece
    if cur in DETERMINE_NOW or (len(cur) >= 6 and "determine".startswith(cur)):
        v = 4.6
    elif cur in DETERMINE_OTHER:
        v = 3.3
    elif cur in RESOLVE:
        v = 1.0
    elif cur == "out":
        v = 3.5 if prev in FIND_VERBS else 0.6
    elif cur in WEAK:
        v = 0.5
    else:
        v = 0.0
    return (prev, cur), float(v)

programs.sol:
"""Approximate a local English phrase signal.

Articles after 'for' score strongly positive; other determiners there,
and articles after other prepositions, score more mildly. Prepositions
after describing words score negative, especially 'in'. Familiar adjectives,
word endings, participles and adverbs approximate this class. Early/late,
quantity changes, and use/employ have separate rules.

Keep only the trailing ASCII word and last token, resetting at document
boundaries. Most tokens receive zero; finer lexical responses are omitted.
"""
import re

READS = ()

# Describing words not covered reliably by the suffix rules below.
ADJECTIVES = set('''good bad great poor best worst better worse high low higher
lower large small larger smaller big deep shallow strong weak stronger weaker
long short wide narrow hot cold hard soft fast slow difficult easy simple
complex clear rich rare thick thin fresh dry wet clean dirty safe happy ready
right wrong free full empty equal perfect unique open closed fine fair true
false superior inferior similar familiar different common certain cheap
expensive healthy aware glad flat round calm pure secure steady lucky shy
important significant relevant confident sufficient deficient frequent
transparent dependent independent critical crucial essential beneficial
instrumental vital proportional necessary suitable stable soluble
greater lesser earlier later further tall bright dark rough sharp dull
accurate adequate inadequate appropriate inappropriate complete incomplete
delicate desperate moderate separate uniform widespread polite superb'''.split())
DIRECTIONS = {'back', 'up', 'down', 'out', 'away', 'ahead', 'behind', 'well'}
CHANGES = {'increase', 'decrease', 'increases', 'decreases', 'reduction', 'growth'}
# Each preposition's sensitivity to a preceding describing word.
PREPOSITIONS = {
    'in': 1.15, 'for': .75, 'on': .60, 'at': .52, 'by': .32,
    'as': .28, 'with': .28, 'to': .12, 'of': .08,
    'from': .12, 'over': .40, 'after': .34, 'before': .25,
}
PARTICIPLES = {'in': -.30, 'for': -.18, 'by': -.13, 'at': -.16}
POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their'}


def describing_strength(word):
    if word in ADJECTIVES:
        return 1.0
    if (len(word) > 4
            and word not in {'table', 'variable', 'available', 'possible'}):
        if word.endswith(('ful', 'less', 'ous', 'ical')):
            return .9
        if word.endswith(('able', 'ible', 'ive')):
            return .6
    if word in DIRECTIONS:
        return .55
    if len(word) > 3 and word.endswith('ly'):
        return .35
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word, last = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    previous = 'for' if last.strip().lower() == 'for' else word.lower()
    current = token.strip()
    value = 0.0
    if current.lower() in ('the', 'a', 'an'):
        value = -.02 if current.islower() else 0.0
        if previous == 'for':
            value = 1.75 if current == 'a' else 1.56
            if current.isupper():
                value = 1.27
            elif current[0].isupper():
                value = .36
            elif last.strip() == 'For' and current == 'the':
                value += .24
        elif previous == 'into':
            value = -.07 if current == 'the' else -.27
        elif previous in PREPOSITIONS:
            if current == 'the' and previous not in ('of', 'in'):
                value = .18
            elif current in ('a', 'an') and previous not in ('by', 'to'):
                value = .30 if previous == 'at' else .14
    elif previous == 'for':
        if current in POSSESSIVES or current in ('this', 'that', 'one', 'two'):
            value = .6
        elif current in ('some', 'any', 'more', 'three', 'four', 'five'):
            value = .3
    elif token == ' ' + current and current in PREPOSITIONS:
        value = -.06 if current == 'in' else .05 if current == 'by' else 0.0
        strength = describing_strength(previous)
        value -= PREPOSITIONS[current] * strength
        if not strength and len(previous) > 3 and previous.endswith(('ed', 'en')):
            value = PARTICIPLES.get(current, 0.0)
        if previous in ('used', 'employed', 'utilized', 'utilised'):
            if current == 'in':
                value = .5
            else:
                value = .3 if current in ('for', 'on', 'by') else .1
        elif current == 'in' and previous in CHANGES:
            value = -.7
        elif previous in ('early', 'late'):
            value = -2.55 if current == 'in' else -1.5 if current == 'on' else -.4
    match = re.search(r'[A-Za-z]+$', token)
    if match:
        word = word + match[0] if match.start() == 0 else match[0]
    else:
        word = ''
    return (doc, word, token), float(value)

