"""layers.0.mlp.down_proj:4233 -- fires on the word right after "for".

When the previous word is "for" and the current word is an article ("the", "a", "an"),
the component is strongly positive (about 1.6). Possessives and demonstratives after
"for" ("this", "his", "your", ...) are weaker (about 0.5). Articles after other
prepositions ("at the", "with a") are only faintly positive (about 0.2). The word "in"
is negative: mildly on average (about -0.13), and clearly after words of change or
comparison ("higher in", "increase in", "difference in"), about -0.7. Everything else is 0.
"""
READS = ()

ARTICLES = {"the", "a", "an"}
DETERMINERS = {"this", "his", "her", "your", "their", "its", "our", "some", "that"}
PREPOSITIONS = {"at", "with", "from", "on", "about", "between", "during", "after", "to", "by", "of", "in"}
CHANGE_WORDS = {
    "higher", "lower", "increase", "increases", "increased", "decrease", "decreases", "decreased",
    "change", "changes", "changed", "difference", "differences", "rise", "rises", "reduction",
    "reduced", "reduce", "increasing", "decreasing", "greater", "less", "more", "better", "worse",
    "larger", "smaller", "high", "low", "up", "down", "gain", "gains", "drop", "growth", "grow",
    "grew", "improvement", "improve", "improved", "significant", "significantly",
}


def step(carry, prefix, upstream):
    words = prefix.token_strings
    if len(words) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    prev = words[-2].strip().lower()
    cur = words[-1].strip().lower()
    if prev == "for":
        if cur in ARTICLES:
            return None, 1.6
        if cur in DETERMINERS:
            return None, 0.5
        return None, 0.0
    if prev in PREPOSITIONS and cur in ARTICLES:
        return None, 0.2
    if cur == "in":
        return None, -0.7 if prev in CHANGE_WORDS else -0.13
    return None, 0.0

