"""A sparse predictor for creative influence and stylistic combination.

Inspiration, influence, boldness and fusion words have negative responses.
Artistic modifiers strengthen 'elements'; technical elements are much weaker.
Source/composition phrases continue on their preposition. Performance is positive.
The first word sometimes responds more strongly. Only 160 recent characters and
one previous word are remembered, with a reset at every document boundary.
Small, unrelated lexical responses are deliberately not modeled.
"""
import re

READS = ()
ART = re.compile(
    r'design|decorat|artwork|artistic|style|fashion|architect|sculpt|fantasy|'
    r'creative|cultur|music|visual|game|branding|painting|craft|imagin|'
    r'cinema|ornament|\bart\b|科幻|奇幻|传统|时尚|设计|設計|风格|風格|'
    r'创意|跑酷|卡通|艺术|趣味|流行|多媒体'
)
TECHNICAL = re.compile(
    r'array|matrix|chemical|atomic|html|xml|vector|finite|data|code|'
    r'nuclear|genetic|polynomial|permutation|multiplexer|数组|容器|化学|矩阵'
)
MODIFIER = re.compile(
    r'(?:design|architectural|sculptural|decorative|branding|artistic|'
    r'aesthetic|futuristic|imaginative|cinematic|stylistic|visual|cultural|'
    r'musical|creative|whimsical|ornamental|steampunk|narrative|rpg|canvas)\W*$'
)
COMBINING = re.compile(
    r'(?:combin(?:e|es|ed|ing)|incorporat(?:e|es|ed|ing)|'
    r'blend(?:s|ed|ing)?|integrat(?:e|es|ed|ing))\W*$'
)
INCORPORATE = {'incorporate', 'incorporates', 'incorporated', 'incorporating'}
BLEND = {'blend', 'blends', 'blending', 'blended'}
INFLUENCE = {'influence', 'influenced', 'influences', 'influencing'}
INTEGRATE = {'integrate', 'integrates', 'integrated', 'integrating', 'infused'}
EXPERIMENT = {'experimenting', 'experimented', 'experimentation'}

# A small calibrated vocabulary within the creative/style concept.
CREATIVE_WORDS = {
    'inspire': -0.13, 'inspiring': -0.13, 'inspirational': -0.13,
    'reminiscent': -0.28, 'homage': -0.28, 'playful': -0.35,
    'aesthetic': -0.15, 'aesthetics': -0.15, 'creativity': -0.15,
    'creative': -0.08,
    '大胆': -0.69, '大膽': -0.69,
    '融合': -0.44, '深度融合': -0.44,
    '勇于': -0.36, '十足': -0.35,
    '风格': -0.22, '風格': -0.22, '气息': -0.22,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, recent, previous, strength = (doc, '', '', 0.0) if first else carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    artistic = bool(ART.search(recent))
    technical = bool(TECHNICAL.search(recent))
    close_art = bool(ART.search(recent[-40:])) and not technical
    value = CREATIVE_WORDS.get(word, 0.0)

    if word in {'element', 'elements'}:
        plural = word == 'elements'
        if MODIFIER.search(recent):
            value = -0.63 if plural else -0.28
            if re.search(r'design\W*$', recent):
                value = -0.83 if plural else -0.40
        elif COMBINING.search(recent) and not technical:
            value = -0.50 if plural else -0.20
        elif close_art:
            value = -0.28 if plural else -0.12
        elif artistic and not technical:
            value = -0.20 if plural else -0.07
        else:
            value = -0.035 if plural else 0.015
    elif word == '元素':
        value = (-0.65 if artistic and not technical
                 else -0.09 if technical else -0.14)
    elif word == 'inspired':
        value = -0.42 if artistic else -0.25
    elif word == '-inspired':
        value = -0.52
    elif word == 'inspiration':
        value = -0.34 if artistic else -0.20
    elif word in INFLUENCE:
        value = -0.35 if close_art else (-0.20 if word != 'influence' else -0.09)
    elif word in INCORPORATE:
        value = -0.27 if artistic else -0.15
    elif word in BLEND:
        value = -0.69 if first else -0.11
    elif word in INTEGRATE:
        value = -0.09 if artistic else 0.0
    elif word in {'bold', 'boldly'}:
        value = -0.29 if close_art else -0.15
    elif word in EXPERIMENT:
        value = -0.28 if artistic else -0.11
    elif word in {'灵感', '靈感'}:
        value = -0.85 if artistic else -0.55
    elif word in {'结合', '相结合', '结合起来', '融入'}:
        value = -0.30 if artistic else -0.18
    elif word == 'performance':
        value = 0.31 if close_art else 0.07

    # Do not treat fragments inside an ASCII identifier as independent words.
    if (token and token[0].isascii() and token[0].isalpha() and recent and
            recent[-1].isascii() and recent[-1].isalnum()):
        value = 0.0

    # Conventional source/composition phrases, rather than general decay.
    if previous == 'inspiration' and word == 'from':
        value = -0.53
    elif previous in {'inspired', '-inspired', 'inspiration'} | INFLUENCE:
        if word in {'by', 'from', 'to'}:
            value = min(-0.10, strength * 1.25)
    elif previous in {'elements', 'element'} | BLEND:
        if word == 'of':
            value = -0.25 if previous in BLEND else min(-0.02, strength * 0.85)
    elif previous in {'reminiscent', 'homage'}:
        if word in {'of', 'to'}:
            value = -0.58 if artistic else -0.38
    elif previous in INCORPORATE or previous in {'experimenting', 'integrates'}:
        if word in {'into', 'with'}:
            value = min(-0.06, strength * 1.2)

    if first:
        if word in {'inspired', 'inspiration', 'experimenting'}:
            value = -0.85
        elif word in {'大胆', '大膽', '融合', '深度融合'}:
            value = -1.0
        elif word == 'elements':
            value = -0.41
    return (doc, (recent + token.lower())[-160:], word, value), value

