"""layers.0.mlp.down_proj:4239, a token-level feature of the first MLP.

The component reads layer 0's MLP hidden state and writes into the residual stream. Its
activation depends mostly on the current token's text, so this program looks only at the
newest token (no context) and predicts its size from a few readable classes:

- chat, tool and reasoning markup (</tool_response>, <|im_start|>, </tool_call>, <think>...)
  is strongest, about 1 to 3;
- Java / PHP / config-style code words and their path forms (java, /vendor, Config,
  .apache, storage, Exception), and place names (US states and cities, Canadian provinces,
  English counties), are moderately positive, about 1 to 1.3;
- fragments of non-Latin text (CJK, kana, Hangul, Cyrillic, Arabic, Thai) and broken UTF-8
  bytes are mildly positive, about 0.2;
- capitalised words and longer English words are weakly positive;
- common function words, punctuation, digits and whitespace are about zero, and a few
  quantity words ("much", "more", "each", "being", "free") are slightly negative.

It is a readable approximation: the component is a broad token-identity feature, so the
lists capture only part of its variance.
"""

import re
import unicodedata

READS = ()

MARKUP = {
    "</tool_response>": 3.2,
    "<tool_response>": -0.3,
    "<|im_start|>": 1.5,
    "<|im_end|>": 0.1,
    "</tool_call>": 2.7,
    "<tool_call>": 1.9,
    "</think>": 1.8,
    "<think>": 1.1,
}

CODE_WORDS = set(
    "java php config exception assert deprecated storage device display status compute "
    "vendor android apache swing cloud pkg www mediatype setter symfony phpunit omitempty "
    "clazz".split()
)

PLACES = set(
    "alabama alaska arkansas colorado connecticut hawaii idaho illinois indiana iowa kansas "
    "kentucky louisiana maine missouri montana nebraska nevada ohio oklahoma oregon "
    "tennessee texas utah vermont virginia washington wisconsin wyoming dakota alberta "
    "ontario quebec manitoba saskatchewan brunswick scotia yorkshire sussex somerset "
    "cumberland devon essex surrey cornwall norfolk suffolk denver edmonton portland "
    "milwaukee dallas boulder louisville hartford sacramento wichita savannah adelaide "
    "halifax bordeaux stuttgart".split()
)

QUIET_WORDS = {"being", "free", "much", "each", "more"}

FUNCTION_WORDS = set(
    "of to the in a an and or is are was were be been for on with at by from as that "
    "this it its which who not but than then there these those he she they we you i his "
    "her their our my your can will would should could may might do does did have has "
    "had if so".split()
)

SCRIPTS = ("CJK", "HIRAGANA", "KATAKANA", "HANGUL", "CYRILLIC", "ARABIC", "THAI")


def _non_latin(text):
    return any(unicodedata.name(ch, "").startswith(SCRIPTS) for ch in text)


def _activation(token):
    if token in MARKUP:
        return MARKUP[token]
    if "�" in token:
        return 0.35
    core = token.strip()
    if not any(ch.isalnum() for ch in core):
        return 0.0
    if _non_latin(core):
        return 0.2
    word = core.lstrip("/.").lower()
    if word in CODE_WORDS:
        return 1.1
    if word in PLACES:
        return 1.25
    if re.search(r"[/._]|[a-z][A-Z]", core):
        return 0.15
    if word in QUIET_WORDS:
        return -0.2
    if word in FUNCTION_WORDS:
        return 0.0
    if core.isascii() and core.isalpha():
        if token.startswith(" ") and core[0].isupper():
            return 0.15
        return 0.12 if len(core) >= 6 else 0.03
    return 0.0


def step(carry, prefix, upstream):
    return None, float(_activation(prefix.token_strings[-1]))

