        letters = [ch for ch in token if ch.isalpha()]
        if not letters:
            score = 0.0
        else:
            word = "".join(letters).lower()
            if word in STOPWORDS and token[:1].isspace():
                score = 0.015
            else:
                length = len(letters)
                if length <= 1:
                    score = 0.10 if any(ord(ch) > 127 for ch in letters) else 0.03
                elif length == 2:
                    score = 0.045
                elif length <= 4:
                    score = 0.10
                elif length <= 7:
                    score = 0.16
                else:
                    score = 0.22

                if any(ord(ch) > 127 for ch in letters):
                    score = max(score, 0.30)
                if any(ch.isupper() for ch in token):
                    score += 0.035

    # Keep the broad lexical guess near the component's small average response.
    return None, 0.8 * score - 0.016

programs.sol:
"""Estimate a short word-junction signal, not a general compound-word parser.

The main positive scores go to short hyphen/underscore continuations after
alphabetic pieces.
The score grows with the preceding piece's length, and declines as more of
what follows the join is spelled out. Compound modifiers strengthen it.
Short consonant or capital fragments get a weaker analogous signal, with
extra weight after common compound roots. NAME_ and test+bed are explicit
identifier/compound cases. En-dash numeric ranges and repeated underscores get
small negative scores. Other tokens normally receive zero. Only the
previous token is remembered, and that memory resets between documents.
"""
import re

READS = ()
MODIFIERS = set("""
well high low hand wood cross water air free small half second third first
full long short right left self hard soft hot cold new old upper lower
light dark deep single double multi non anti back heart head
""".split())
COMPOUND_ROOTS = set("""
heart blood hand foot head tooth ear eye arm back wheel ship fire snow wood
water air wire table screen sand stone grass house home road paper sun wind
""".split())
BED_COMPOUNDS = {'test', 'river', 'stream', 'road', 'foot', 'hot', 'child'}
WORD_ENDINGS = {'s', 'n', 'r', 't', 'd', 'ed', 'es', 'er', 'ers', 'ing', 'ly'}

# Shape: offset, length slope, word-start bonus, compound-modifier bonus.
DASH_SHAPES = {
    'bare': (0.05, 0.22, 0.055, 0.095),
    'lower initial': (-0.11, 0.245, 0.08, 0.05),
    'upper initial': (-0.10, 0.18, 0.045, 0.025),
    'two letters': (-0.075, 0.065, 0.025, 0.03),
    'three letters': (-0.08, 0.035, 0.025, 0.025),
    'longer': (-0.07, 0.017, 0.016, 0.0),
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    match = re.search(r'([^\W\d_]+)$', previous)
    letters = match[1] if match else ''
    n = min(len(letters), 5)
    root = letters.lower()
    value = 0.0
    if token.startswith('-'):
        tail = token[1:]
        if not tail or tail.isalpha():
            if not tail:
                shape = 'bare'
            elif len(tail) == 1:
                shape = 'lower initial' if tail.islower() else 'upper initial'
            else:
                shape = {2: 'two letters', 3: 'three letters'}.get(
                    len(tail), 'longer'
                )
            bias, slope, start_bonus, modifier_bonus = DASH_SHAPES[shape]
            slope += start_bonus * bool(previous[:1].isspace())
            slope += modifier_bonus * (root in MODIFIERS)
            value = bias + slope * min(n, 4)
            if letters.isupper():
                if shape == 'lower initial':
                    value -= 0.04 * min(n, 4)
                elif shape == 'longer':
                    value -= 0.02 * min(n, 4)
            if not letters and not tail:
                value = 0.03 if previous[-1:].isdigit() else -0.07
            elif not letters and len(tail) == 1:
                value = -0.015
    elif token.startswith('_'):
        tail = token[1:]
        if not tail:
            value = 1.16 if letters == 'NAME' else max(0.08, 0.12 * n)
        elif tail.isalpha() and len(tail) == 1:
            value = -0.15 + 0.11 * min(n, 4) + 0.01 * max(0, n - 4)
            if not letters:
                value = -0.025
        elif tail.isalpha():
            value = -0.04 if n <= 2 else -0.025
        elif token == '__':
            value = -0.03
        elif set(token) == {'_'}:
            value = -0.18
    elif token == 'bed' and root in BED_COMPOUNDS:
        value = 0.8 if root == 'test' else 0.65
    elif token in {'‐', '‑', '\xad'}:  # Hyphen, nonbreaking hyphen, soft hyphen.
        value = 0.4 + 0.2 * min(n, 4)
    elif token == '–':  # En dash also commonly marks numeric ranges.
        value = -0.11 if previous[-1:].isdigit() else min(0.12 * n, 0.5)
    elif token == '—':
        value = min(-0.12 + 0.07 * n, 0.13)
    elif token.isascii() and token.isalpha() and n:
        size = max(0, n - 2)
        if len(token) == 1 and token.isupper():
            value = 0.15 * size + 0.15 * (root in COMPOUND_ROOTS)
        elif len(token) <= 2 and token not in WORD_ENDINGS:
            if not any(c in 'aeiouy' for c in token):
                value = (0.105 if len(token) == 1 else 0.065) * size
                if root in COMPOUND_ROOTS:
                    value += 0.6 if len(token) == 1 else 0.4
        elif len(token) == 1 and token in WORD_ENDINGS:
            value = 0.03 * max(0, n - 3)
    return (doc, token), float(value)

