"""A partial lexical/phrase model of a very weak component.

It distinguishes obligation from futurity before "be", recognizes a few
qualifying/discourse words, and treats "address" differently as a verb and
as a noun.  Chat delimiters have their own fixed baselines.  Other tokens
receive zero: the component's many irregular lexical responses are omitted.
"""

READS = ()
BE_AFTER = {
    'must': .174, 'should': .055, 'might': .050, 'could': .024,
    'can': -.017, 'would': -.016, 'will': -.040, 'shall': -.085,
}
MARKERS = {
    '<|endoftext|>': .018, '<|im_start|>': .023, '<|im_end|>': .009,
    '<think>': .043, '</think>': -.121, '</tool_call>': -.059,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, end = ('', '') if carry is None or carry[0] != doc else carry[1:]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    value = MARKERS.get(word, 0.)
    # A subword without a preceding word boundary is not a grammatical word.
    if raw[:1].isspace() or not end.isalpha():
        if word == 'be':
            value = BE_AFTER.get(previous, 0.)
        elif previous == 'there' and word in {'is', 'are'}:
            value = -.060 if word == 'is' else -.045
        elif word in {'either', 'neither'}:
            value = .108
        elif word == 'yet':
            value = -.105
        elif word in {'necessary', 'warranted'}:
            value = .110 if word == 'necessary' else .300
        elif word in {'remain', 'remains', 'remained'}:
            value = .130
        elif word in {'therefore', 'accordingly'}:
            value = .058 if word == 'therefore' else .197
        elif word == 'possible':
            value = 0. if previous in {'not', "n't"} else .055
            if previous == 'as':
                value = .119
        elif word == 'particular':
            value = -.243 if previous == 'in' else -.035
        elif word in {'case', 'example'} and previous == 'this':
            value = -.150
        elif word == 'address':
            verbs = {'to', 'can', 'could', 'must', 'should', 'we', 'they'}
            value = .250 if previous in verbs else -.100
            if previous in {'ip', 'physical', 'postal', 'your', 'my', 'memory'}:
                value = -.210
        elif word in {'addressed', 'addressing'}:
            value = .450 if previous == 'be' else .230
        elif word in {'most', 'various', 'often'}:
            value = .067
        elif word in {'some', 'any', 'all', 'every', 'first', 'always'}:
            value = -.026
        elif word in {'few', 'enough', 'another'}:
            value = -.058
        elif word == 'only':
