"""A negative spelling response centered on the short syllable 'te'.

Bare te/Te/TE is strongest; case, token boundaries, length and the preceding
letter modify its strength. Short Romance/Germanic te/ten/tes endings also
respond. Explicit exceptions cover finite/definite, byte, suite, prote-,
tea/teach-, techni-/tele-, and several other-script spellings of te. Other
tokens get zero. This ignores finer lexical and sentence-dependent effects;
only the immediately preceding token is consulted, within the same document.
"""
READS = ()
VOWELS = 'aeiouy'


def te_fragment(word, boundary):
    lower = word.lower()
    n = len(lower)
    if lower == 'te':
        if word == 'Te':
            return -4.15
        if word == 'TE':
            return -3.4 if boundary else -2.85
        return -3.25 if boundary else -2.4
    if n == 3:
        previous = lower[0]
        if previous == 'a':
            return -1.4 if boundary else -0.7
        if previous == 'i':
            return -0.9
        if previous == 'o':
            return -1.8
        if previous in 'eu':
            return -1.3
        if previous == 's':
            return -1.3 if boundary else -1.8
        return -1.2 if previous in 'hkt' else -1.8
    if n == 4:
        # Vowel + consonant + te is a compact inflectional fragment.
        if lower[0] in VOWELS:
            if lower[1] in 'nr':
                return -1.05
            if lower[1] == 's':
                return -0.45 if boundary else -0.9
            return -0.5
        if lower[1] == 'y':
            return -1.0             # byte-like spelling
        return -0.08 if boundary else -0.3
    return -0.08 if boundary else -0.2 if n == 5 else -0.07


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('_-/(.')
    lower = word.lower()
    boundary = token[:1].isspace()
    value = 0.0
    if lower in ('finite', 'infinite', 'definite'):
        value = -0.75
    elif lower in ('suite', 'suites'):
        value = -1.1
    elif lower in ('byte', 'bytes'):
        value = -0.9
    elif lower == 'prote':           # protein/protease combining stem
        value = -2.35
    elif lower.endswith('te'):
        value = te_fragment(word, boundary)
    elif lower.endswith(('ten', 'tes')):
        if len(lower) == 3:
            value = -0.8 if lower.endswith('n') else -1.65
        else:
            value = te_fragment(word[:-1], boundary)
            value *= 0.5 if lower.endswith('n') else 0.6
    elif lower.startswith('teach'):
        value = -0.6
    elif lower in ('tea', 'teas'):
        value = -1.15
    elif lower.startswith(('techni', 'tele')):
        value = -0.4
    elif lower == 'те':
        value = -1.5
    elif lower.endswith('те'):
        value = -0.35
    elif word == 'テ':
        value = -1.9
    elif word.endswith('テ'):
        value = -0.8
    elif word.endswith('て'):
        value = -0.5 if len(word) == 1 else -0.35
    elif word == '테':
        value = -1.5
    elif word == '特':
        value = -1.05
    if word == 'te' and not boundary and len(prefix.token_strings) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
