STRONGEST = {"individual", "个人", "個人", "개인"}
STRONG = {"individuals", "individually", "individ", "personal", "personally", "personalized"}
MEDIUM = {"person", "persons", "single", "singles", "一个人", "个体"}
WEAK = {"people", "someone", "everyone", "anyone", "alone", "oneself", "professional",
        "profile", "career", "个性"}
SELF = {"self", "myself", "yourself", "himself", "herself", "themselves", "itself", "own", "自己"}

LEVELS = [(STRONGEST, 6.5), (STRONG, 4.0), (MEDIUM, 3.0), (WEAK, 1.2), (SELF, 0.8)]


