"""A sparse lexical approximation, strongest on Chinese literary-name vocabulary.

A token's Chinese word class sets its response. Names and content characters
become more negative when recent text contains classical/court diction and is
mostly character-by-character Chinese. This register test uses only the last
64 tokens and resets at document boundaries; it does not parse actual names.
Separate small rules encode observed quantifier, literal, degree-word and
message-boundary responses. Most token-specific variation is left unexplained.
"""
from collections import deque

READS = ()

SURNAMES = set(
    '王李张刘陈杨黄赵吴周徐孙马朱胡郭何林高罗郑梁'
    '谢宋唐许韩冯邓曹彭曾萧田董潘袁于蒋蔡余杜叶程'
    '苏魏吕丁任沈姚卢姜崔钟谭陆汪范金石廖贾夏韦傅'
    '方白邹孟熊秦邱江尹薛阎段雷侯龙史陶黎贺顾毛郝'
    '龚邵万钱严武戴莫孔向汤張劉陳楊黃趙吳孫馬羅鄭'
    '謝許韓馮鄧蕭蔣葉蘇呂盧鍾譚陸賈韋鄒閻龍賀顧龔'
    '萬錢嚴湯'
)
COMPOUNDS = {
    '上官', '东方', '令狐', '公孙', '公孫',
    '司馬', '司马', '夏侯', '宇文', '尉迟',
    '尉遲', '慕容', '東方', '欧阳', '歐陽',
    '皇甫', '諸葛', '诸葛',
}
NAME_ELEMENTS = set(
    '玄熙昭弘懿钦欽恬景轩軒羲献獻桓奉霜玉'
)
ARCHAIC = set(
    '曰矣焉吾汝朕卿兮哉遂臣诏詔乃皆'
)
COURT = set(
    '皇帝君王侯丞宰御殿宫宮兵军軍将將宗玄仙曹魏蜀'
    '吴吳汉漢'
)
COURT_WORDS = {
    '丞相', '內閣', '内阁', '司馬', '司马',
    '天子', '奉命', '宰相', '将军', '將軍',
    '朕', '朝廷', '皇上', '皇帝', '諸葛',
    '诸葛', '道長', '道长', '陛下',
}
FUNCTIONS = set(
    '的一是了不在有和与與及为為而之乎者也于於其以'
    '所将將會会让讓這这那他她它我你们們就都得着著'
    '吧吗嗎呢但或又且亦乃则則即若虽雖能可無无没沒'
    '被把从從對对比很更已只每各'
)

def han(c):
    return '\u3400' <= c <= '\u9fff'


# Rounded ordinary/literary training estimates; compound-name extremes damped.
CHINESE_RESPONSES = {
    'compound surname': (-0.18, -0.55),
    'name element': (-0.12, -0.44),
    'surname': (-0.01, -0.22),
    'archaic word': (-0.02, -0.13),
    'function word': (0.0, -0.03),
    'court word': (-0.02, -0.11),
    'merged word': (-0.006, -0.007),
    'character': (0.002, -0.08),
}

# These classes are lexical associations, not one unified semantic axis.
DUAL_QUANTIFIERS = {'both', 'neither'}
UNRESTRICTED_QUANTIFIERS = {'all', 'any', 'either'}
UNRESTRICTED_OBJECTS = {'everything', 'anything'}
SINGULARITY = {'single', 'unique', 'singular'}
LATER_ORDINALS = {
    'third', 'fourth', 'fifth', 'sixth', 'seventh', 'eighth', 'ninth',
}
BOOLEAN_LITERALS = {'true', 'false'}
CHINESE_DEGREE = {'更', '最', '更加', '更是', '更具'}
TOOL_BOUNDARIES = {
    '<tool_call>': -0.049,
    '</tool_call>': 0.019,
    '<tool_response>': 0.022,
    '</tool_response>': 0.052,
}

def lexical_response(token):
    word = token.lower()
    if word in DUAL_QUANTIFIERS:
        return -0.082
    if word in UNRESTRICTED_QUANTIFIERS:
        return -0.025
    if word in UNRESTRICTED_OBJECTS:
        return -0.073
    if word == 'several':
        return -0.073
    if word in SINGULARITY:
        return 0.075
    if word in LATER_ORDINALS:
        return -0.064
    if word in BOOLEAN_LITERALS:
        return 0.031
    if word == 'null':
        return -0.13 if token == 'NULL' else -0.09
    if token in CHINESE_DEGREE:
        return 0.16
    if word == 'please':
        return 0.094
    if token == '✓':
        return 0.084
    return TOOL_BOUNDARIES.get(token, 0.0)

def chinese_class(token, single, chinese, court):
    for name, words in (
        ('compound surname', COMPOUNDS),
        ('name element', NAME_ELEMENTS),
        ('surname', SURNAMES),
        ('archaic word', ARCHAIC),
        ('function word', FUNCTIONS),
    ):
        if token in words:
            return name
    if court:
        return 'court word'
    if chinese:
        return 'character' if single else 'merged word'
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, totals = deque(), [0.0]*4
    else:
        _, history, totals = carry
    token = prefix.token_strings[-1].strip()
    chinese = bool(token) and all(han(c) for c in token)
    single = chinese and len(token) == 1
    court = (single and token in COURT) or token in COURT_WORDS
    # Count classical diction; penalize merged words and Japanese kana.
    diction = totals[2] / 64.0
    character_style = (
        totals[0] - 1.5*totals[1] - 2*totals[3]
    ) / 64.0
    literary = diction >= 0.02 and character_style >= 0.3
    category = chinese_class(token, single, chinese, court)
    if category:
        value = CHINESE_RESPONSES[category][int(literary)]
    else:
        value = 0.0006
    value += lexical_response(token)

    metrics = (
        float(single), float(chinese and not single),
        float(token in ARCHAIC) + 0.5*float(court),
        float(any('\u3040' <= c <= '\u30ff' for c in token)),
    )
    history.append(metrics)
    for i, x in enumerate(metrics):
        totals[i] += x
    if len(history) > 64:
        for i, x in enumerate(history.popleft()):
            totals[i] -= x
    return (doc, history, totals), float(value)

