        if previous in {'refer', 'refers', 'referred'}:
            return -0.15
    if token == ' of' and previous in {
        'each', 'most', 'some', 'variety', 'types', 'form', 'forms'
    }:
        return -0.085
    if token == ' the' and previous == 'all':
        return -0.107
    if token == ' a':
        if previous in {'is', 'are'}:
            return 0.037
        if previous == 'at':
            return -0.066
