    elif word in {'spanish', 'spain', 'santa', 'santiago'}:
        value = 0.23
    elif word in {'american', 'english', 'british', 'australian'}:
        value = -0.08
    elif word in ANGLOPHONE_CITIES:
        value = -0.12
    elif token == ' de':
        value = 0.14 - 0.44 * french
        if prev in {'a', 'o', 'as', 'os', 'io', 'ro', 'ia'}:
            value += 0.13
    elif token == ' del':
        value = 0.35
    elif token == ' dos':
        value = 0.18
    elif token == ' por':
        value = 0.16
    elif token in {' da', ' do'}:
        value = 0.02 if token == ' do' else 0.055
        if prev.isalpha():
            value += 0.09
        if token == ' do' and prev.strip().lower() in {
            'can', 'could', 'should', 'would', 'will', 'we'
