        current_word = word if word.isalpha() else ''
    else:
        current_word = (current_word + word)[-60:]
    return (doc, token, current_word, french), value

"""A multilingual detector for the word 'code', not for programming syntax.

Complete code words fire strongly. Translations and code-related words or
fragments have graded responses. Exit/error-code phrases fire more strongly;
source code, markup tags, and encoding fragments fire less strongly.
Only the current token and previous token in the same document are used.
"""
READS = ()

# Translations and Chinese compounds containing the word 'code'.
CODE_WORDS = {
    '代码': 4.35, '编码': 3.6, '二维码': 3.45, '扫码': 2.65,
    '密码': 2.1, '号码': 1.95, '数码': 2.0,
    'код': 3.8, 'コード': 3.2, '코드': 3.4,
    'código': 3.0, 'codigo': 2.9, 'mã': 2.5,
    'kod': 1.7, 'kode': 2.2,
}

# Familiar code compounds and token fragments of code-related words.
RELATIVES = {
    'unicode': 1.4, 'vscode': 1.4, 'leetcode': 1.4,
    'opcode': 2.5, 'bytecode': 2.5, 'postcode': 2.5,
    'getcode': 5.4, 'setcode': 4.7, 'hashcode': 2.5,
    'coding': 2.3, 'coded': 2.0, 'codec': 2.0, 'codecs': 2.0,
    'cod': 1.7, 'codegen': 1.5, 'oding': 1.1,
    'ode': 0.3, 'odes': 0.65, 'ocode': 1.2,
    'ancode': 4.4,  # The suffix in 'scancode'.
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('._-/($["\'`').lower()
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    before = previous.strip().lstrip('._-/($["\'`').lower()
    value = CODE_WORDS.get(word, RELATIVES.get(word, 0.0))

    if word in {'code', 'codes'}:
        value = 5.1
        if before == 'source':
            value = 3.6
        elif before in {'exit', 'error', 'status'}:
            value = {'exit': 6.0, 'error': 6.3, 'status': 5.6}[before]
        elif previous.endswith('{@'):
            value = 2.8
        elif previous.endswith('<') or previous.endswith('</'):
            value = 3.5
        elif before in {'de', 'en'} and not token[0].isspace():
            value = 2.2
        elif token.startswith(('/', '(')) or token == 'CODE':
            value = 4.4
    elif word in {'码', '碼'}:
        value = 7.9 if word == '码' else 6.3
        if previous.endswith('解'):
            value = 3.6  # Decoding.
        elif previous.endswith(('号', '號')):
            value = 5.5  # Number codes.
        elif previous.endswith('編'):
            value = 2.3  # Traditional-Chinese encoding.
        elif previous.endswith('程式'):
            value = 4.0  # Traditional-Chinese program code.
    elif word.startswith('encod'):
        value = 1.2 if word == 'encoded' else 0.9
    elif word.startswith('decod'):
        value = 0.7
    elif word.endswith('code') and word not in RELATIVES:
        value = 3.5  # Compound identifiers such as statusCode and keyCode.
    return (document, token), value

