"""Detect strong programming-code mentions and weaker encoding-related words."""
READS = ()


def _has_word(text, word):
    start = text.find(word)
    while start >= 0:
        end = start + len(word)
        before = text[start - 1] if start else " "
        after = text[end] if end < len(text) else " "
        if not before.isalpha() and not after.isalpha():
            return True
        start = text.find(word, start + 1)
    return False


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if "代码" in token:
        return None, 4.5
    if _has_word(token, "код"):
        return None, 3.6
    if _has_word(token, "code"):
        return None, 5.0
    if "code" in token:
        return None, 1.2
    if "encoding" in token or "decoding" in token:
        return None, 0.8
    return None, 0.0

