"""A lexical detector for 'one' and unspecified people, things and places.

The strongest responses are to indefinite pronouns such as 'something'.
Generic nouns and relative-day words respond more weakly. 'One' is weaker
inside another word or after numerical qualifiers ('only', 'least', etc.).
The only remembered context is the preceding token, reset per document.
Unrecognized forms receive zero; this does not parse meaning in general.
"""

READS = ()

THING_PRONOUNS = {'something': 1.75, 'anything': 1.45,
                  'everything': 1.36, 'nothing': 1.08}
PERSON_PRONOUNS = {'someone', 'anyone', 'everyone'}
BODY_PRONOUNS = {'somebody', 'anybody', 'everybody', 'nobody'}
PLACE_PRONOUNS = {'somewhere', 'anywhere', 'everywhere', 'nowhere'}
GENERIC = {'thing': 0.53, 'things': 0.81, 'stuff': 0.36,
           'people': 0.36, 'others': 0.64, 'ones': 0.65,
           'life': 0.88, 'lives': 0.73, 'society': 0.62,
           'societies': 0.52, 'societal': 0.60}
DAYS = {'today': 0.71, 'tomorrow': 0.59, 'yesterday': 0.39,
        'tonight': 0.35, 'everyday': 0.44, 'daily': 0.18}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    raw = token.lstrip(' \t\r\n_.,(:[{\'"“‘—/')
    hyphen = raw.startswith('-')
    raw = raw[1:] if hyphen else raw
    word, prev = raw.lower(), previous.strip().lower()
    separate = raw != token or not previous[-1:].isalpha()

    if word == 'one':
        value = 1.30 if separate else 0.19
        if raw == 'One':
            value = 1.45 if separate else 1.15
        elif raw == 'ONE':
            value = 1.02 if separate else 0.15
        if separate and prev in {'only', 'least', 'exactly', 'first'}:
            value = 0.87
        elif separate and prev in {'no', 'number'}:
            value = 0.73
        elif separate and prev in {'a', 'the'}:
            value = 1.10
    elif word in THING_PRONOUNS:
        value = THING_PRONOUNS[word]
        if not token[:1].isspace():
            value -= 0.18
    elif word in PERSON_PRONOUNS:
        value = 1.08
    elif word in BODY_PRONOUNS:
        value = 0.52 if word == 'nobody' else 0.80
    elif word in PLACE_PRONOUNS:
        value = 0.60 if word == 'anywhere' else 0.38
    elif word in GENERIC:
        value = GENERIC[word]
        if not separate and word != 'thing':
            value *= 0.4
        if raw == 'Society':
            value = 0.35
    elif word in DAYS:
        value = DAYS[word]
    elif word == 'al' and prev == 'et':
        value = 0.73 if previous.startswith(' ') else 0.33
    else:
        value = 0.0
    if hyphen:
        value *= 0.6
    return (doc, token), float(value)

