"""Approximate a sparse word detector: indefinite references, things, people, and life."""

READS = ()

INDEFINITE_THINGS = {"something", "anything", "everything", "nothing"}
INDEFINITE_PEOPLE = {
    "someone", "anyone", "everyone", "noone", "nobody",
    "somebody", "anybody", "everybody",
}

GENERAL_THINGS = {"thing", "things", "stuff", "ones"}
PEOPLE = {"people", "person", "persons", "others", "society"}
LIFE_WORDS = {"life", "lives", "today"}


def step(carry, prefix, upstream):
    """Predict high activation for standalone words in a few recurring semantic groups."""
    raw = prefix.token_strings[-1]
    word = raw.strip().casefold()
    doc = prefix.document_ids[-1]
    previous_char = ""
    previous_word = ""
    if carry is not None and carry[0] == doc:
        previous_char, previous_word = carry[1], carry[2]

    if word in INDEFINITE_THINGS:
        value = 1.5
    elif word in INDEFINITE_PEOPLE:
        value = 1.05
    elif word == "one":
        # An unspaced lower-case piece can be the end of a larger word.
        value = 0.55 if raw == "one" and previous_char.isalpha() else 1.3
    elif word == "al" and previous_word == "et":
        value = 0.72  # the citation abbreviation “et al.”
    elif word in GENERAL_THINGS:
        value = 0.65
    elif word in PEOPLE:
        value = 0.45
    elif word in LIFE_WORDS:
        value = 0.75
    else:
        value = 0.0

    return (doc, raw[-1:] if raw else "", word), value

programs.haiku:
"""Component layers.0.mlp.down_proj:4255: a copula/auxiliary-verb detector for embedded clauses.

What it responds to, in plain terms:
  * Almost nothing, most of the time. Its large responses are on finite forms of "be"
    ("is", "are", "was", "were", "'re"), and weaker ones on other auxiliaries and modals
    ("be", "have", "can", "could", "would", "should", "did", ...).
  * Strongest when the verb sits inside a clause opened by a wh-word or "if" / "whether"
    a word or two earlier, so the verb follows its own subject:
    "what technology [is] working", "how the data [is] used", "when the train [is] moving".
    The response is largest one or two words after the wh-word and fades with distance.
    A "that" clause ("... that the data is ...") gives a medium response.
  * Outside those clauses, a verb right after an ordinary lowercase word, usually a noun
    or a pronoun such as "it", "they", "you", gives a small response. A verb after a
    function word ("to", "which", "can", "not") or after a capitalised sentence start
    ("This is", "It is", "We are") gives almost none.

The program is a short rule over the last few tokens. It keeps no state.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

COPULA = {"is", "are", "was", "were", "'re", "’re"}
AUXILIARY = {
    "be", "been", "being", "am", "have", "has", "had", "do", "does", "did", "can",
    "could", "will", "would", "should", "might", "may", "must", "shall",
}
WH_WORDS = {"what", "when", "where", "how", "if", "whether", "why"}
# Words after which a verb has no ordinary noun or pronoun subject right before it.
NOT_SUBJECT = {
    "to", "that", "which", "who", "and", "or", "but", "not", "also", "only", "can", "may",
    "must", "cannot", "always", "never", "have", "has", "had", "just", "still", "even",
    "often", "the", "a", "an", "of", "in", "on", "with", "for", "as", "if", "so", "then",
    "than",
}
SENTENCE_END = {".", "?", "!"}


def step(carry, prefix, upstream: Mapping):
    tokens = prefix.token_strings
    doc = prefix.document_ids
    word = tokens[-1].strip().lower()
    if word not in COPULA and word not in AUXILIARY:
        return None, 0.0
    copula = word in COPULA

    # Look back up to six tokens, within this sentence and document, for a clause marker.
    back = len(tokens) - 2
    wh_gap = None
    that_seen = False
    for steps in range(6):
        j = back - steps
        if j < 0 or doc[j] != doc[-1]:
            break
        w = tokens[j].strip().lower()
        if w in SENTENCE_END or "\n" in tokens[j]:
            break
        if w in WH_WORDS:
            wh_gap = steps
            break
        if w == "that":
            that_seen = True

    if wh_gap is not None:
        # Strongest one or two words after the wh-word; weaker further away.
        strong = 1.6 if wh_gap in (1, 2) else (1.1 if wh_gap in (0, 3) else 0.8)
        return None, (strong if copula else 0.4 * strong)
    if that_seen:
        return None, (0.5 if copula else 0.2)

    # Otherwise: a verb right after an ordinary lowercase word responds weakly.
    if back >= 0 and doc[back] == doc[-1]:
        prev = tokens[back].strip()
        if prev[:1].islower() and prev.lower() not in NOT_SUBJECT:
            return None, (0.2 if copula else 0.08)
    return None, 0.0

