    "difference": -2.0, "differences": -1.8, "différence": -2.0,
    "differ": -1.1, "differs": -1.1, "differential": -1.1,
    "differed": -0.7, "differing": -0.7, "diffusion": -0.7,
    "diffuse": -0.7, "difficulty": -0.7, "difficulties": -0.7,
    "change": -0.17, "changed": -0.17, "changes": -0.7,
    "similarity": -0.83, "similarities": -0.83,
}
SPELLING_RESPONSES = {
    "iffs": -1.8, "iffer": -1.8, "iffe": -2.2,
    "ifference": -2.75, "ifferences": -2.75,
    "sniff": -4.0, "stiff": -1.9,
    "cliff": -1.5, "cliffs": -1.5, "cliffe": -1.5,
    "ff": -0.55, "ffi": -0.55, "ffe": -0.55,
    "ffer": -0.55, "uff": -0.55, "itt": -1.25,
    "ify": -0.3, "ified": -0.3, "ifier": -0.3, "ifiers": -0.3,
    "traffic": -0.83, "coefficient": -0.5, "coefficients": -0.5,
}
COMPUTATION = dict.fromkeys(
    ("compute", "computed", "computing", "construct"), 0.43
)
# Chinese words for difference, generate, and produce/arise.
CHINESE = {"差": -2.45, "差异": -1.17, "生成": 1.88, "产生": 0.7}
VALUES = {
    **PRODUCTION, **GENERATION, **DIFFERENCES,
    **SPELLING_RESPONSES, **COMPUTATION, **CHINESE,
}
CREATION_VERBS = {
    "produce", "produced", "produces", "producing",
    "generate", "generated", "generates", "generating",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    token = prefix.token_strings[-1]
    text = token.strip()
    bare = text.lstrip("._-/(")
    word = bare.lower()
    spaced = token[:1].isspace()
    capital = bare[:1].isupper()
    value = VALUES.get(word, 0.0)

    if text == "@@":
        value = -4.8 if token.endswith("\n") else (-6.7 if spaced else -7.35)
    elif text == "+++":
        value = -1.0
    elif text == "@":
        value = -0.25
    elif word in {"diff", "diffs"}:
        value = -5.1 if spaced else -5.8
        if capital:
            value = -4.25 if spaced else -4.85
        if text.isupper():
            value = -3.8
        if text.startswith(("_", "(")):
            value = -3.45
        if text.startswith("."):
            value = -6.5
    elif word == "iff":
        value = -1.8 if spaced else -4.6
    elif word in PRODUCTION:
        if not spaced:
            value *= 0.72
        if capital and word == "producer":
            value = 1.15
    elif word == "changes" and capital:
        value = -1.0
    elif len(word) == 4 and word.endswith("itt"):
        value = -0.9

    if word in {"a", "an", "the"} and previous in CREATION_VERBS:
        value = 0.52
    elif word == "of":
        if previous in {"production", "generation"}:
            value = 0.61
        elif previous in {"produce", "producer", "produced"}:
            value = 1.0
        elif previous in {"diff", "difference", "differences"}:
            value = -0.34
    elif previous == "produ" and word in {"ced", "ces", "cing"}:
        value = 2.2
    elif previous == "diff" and token == " --":
        value = -0.37
    return (doc, word), float(value)

