"""layers.0.mlp.down_proj:4258 -- a "quite" detector.

The component reads a token's own identity (context barely matters) and responds to:
  * the word "quite" itself, very strongly (about 8.4);
  * other degree words meaning "to some / considerable extent": rather, pretty,
    relatively, fairly, somewhat, very, considerably, entirely, completely, German ganz,
    and the Chinese 很, 相当, 十分, 非常, 較 (about 1.1);
  * the wh-word "what" / "whatever" (about 1.1);
  * words beginning "quad" or "quit" (quadratic, quad, quit), about 2.0;
  * other words beginning with the letter q (quote, quarter, quantum, quiet, Qu, qu, Q ...),
    about 1.0, except spellings beginning "que", "qual" or "quick" (que, question, query,
    queue, quality, quickly ...), which stay near zero; a lone "q" is about 0.5.
Everything else predicts 0.
"""

READS = ()

DEGREE = {
    "rather", "pretty", "relatively", "fairly", "somewhat", "very", "ganz",
    "considerably", "considerable", "entirely", "completely",
    "很", "相当", "相當", "十分", "非常", "較",
}
WH = {"what", "whatever"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word == "quite":
        value = 8.4
    elif word in DEGREE or word in WH:
        value = 1.1
    elif word == "q":
        value = 0.5
    elif word.startswith(("quad", "quit")):
        value = 2.0
    elif word.startswith("q") and not word.startswith(("que", "qual", "quick")):
        value = 1.0
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Approximate the negative response to indefinite and quantified entities.

The rules distinguish 'is a' from 'and a', and 'for all' from other
uses of 'all'. They also recognize existence expressions, mathematical
entity words, and a few non-English quantifier spellings/stems. A flag
for mathematical words or notation in the previous sixteen tokens
strengthens selected responses. Context resets at document boundaries;
unrecognized tokens normally return zero. This deliberately leaves out
much of the component's remaining token-specific variation.
"""
READS = ()

QUANTIFIERS = {'any': -0.39, 'some': -0.29, 'all': -0.08,
               'each': -0.10, 'every': -0.17}
MATH_NOUNS = {'integer': -0.62, 'integers': -0.90,
              'number': -0.16, 'numbers': -0.59,
              'element': -0.40, 'elements': -0.48,
              'point': -0.09, 'points': -0.11,
              'scalar': -0.34, 'coefficients': -0.22, 'vectors': -0.20,
              'inputs': -0.38, 'nodes': -0.21}
SELECTION = set('find choose pick fix select'.split())
CREATION = set('create creates creating provide provides providing '
               'produce produces generate generates obtain take takes '
               'return returns define defines'.split())
REPRESENTATION = set('form forms represent represents denote denotes'.split())


def lexical_response(token, previous):
    word = token.strip()
    prev = previous.strip().lower()
    value = 0.0
    whole_word = token.startswith(' ')
    if whole_word and word in ('a', 'an'):
        value = -0.07
        if not previous:
            value = -0.85
        elif prev in ('exists', 'exist'):
            value = -2.0
        elif prev == 'is':
            value = -0.69 - 0.07 * (word == 'an')
        elif prev in ('be', "'s"):
            value = -0.40
        elif prev in ('was', 'are', 'being'):
            value = -0.30
        elif prev in ('been', '’s', 'were', 'has', 'not'):
            value = -0.16
        elif prev in SELECTION or prev in ('given', 'there'):
            value = -0.75
        elif prev in REPRESENTATION or prev in ('give', 'gives'):
            value = -0.38
        elif prev in CREATION or prev in ('for', 'if', 'whether', '='):
            value = -0.24
        elif prev in ('of', 'at', 'by', 'to', 'that', 'which'):
            value = -0.12
        elif prev in ('and', 'as', ',', 'in', 'on', 'from', 'with',
                      'make', 'made', 'had', 'have', 'such', 'like',
                      'through', 'over', 'using', 'use'):
            value = 0.0
        if previous.strip() == 'For':
            value -= 0.35
    elif whole_word and word in QUANTIFIERS:
        value = QUANTIFIERS[word]
        indefinite = word in ('any', 'some')
        if not previous:
            value -= 0.90
        elif prev == 'for':
            value = {'any': -1.20, 'some': -1.05, 'all': -0.82,
                     'each': -0.76, 'every': -1.25}[word]
            if previous.strip() == 'For':
                value -= 0.25
        elif prev == 'is' and indefinite:
            value = -1.17
        elif prev in ('be', 'there', "'s") and indefinite:
            value = -0.88
        elif prev in ('are', 'was', 'were') and indefinite:
            value = -0.58
        elif prev in SELECTION:
            value -= 0.50
        elif prev in ('if', 'between', 'then', 'where', 'that'):
            value -= 0.20
        elif prev in ('in', 'on', 'have'):
            value += 0.13
        elif prev in ('without', 'see', 'before', 'produce'):
            value = 0.0
        elif prev in ('it', 'them', 'us', 'up') and not indefinite:
            value = 0.12
        elif prev == 'at' and indefinite:
            value -= 0.28
        elif prev in ('of', 'to', 'by', 'from'):
            value -= 0.10
        elif prev in (',', 'and', 'with') and indefinite:
            value += 0.10
    elif whole_word and word in MATH_NOUNS:
        value = MATH_NOUNS[word]
        if prev in QUANTIFIERS:
            value -= 0.40
        elif prev in ('a', 'an'):
            value -= 0.30 if word in ('point', 'points', 'element') else 0.20
        elif word in ('number', 'numbers'):
            if prev in ('real', 'natural'):
                value -= 0.90
            elif prev in ('rational', 'complex', 'random'):
                value -= 0.60
            elif prev in ('prime', 'even', 'odd', 'whole'):
                value -= 0.30
        elif word in ('point', 'points') and prev in (
                'fixed', 'certain', 'one', 'two', 'three', 'single'):
            value -= 0.25
    elif whole_word and word in ('exist', 'exists'):
        value = -1.5 if prev == 'there' else -0.25
    elif whole_word and word in ('arbitrary', 'finite', 'fixed', 'given', 'fix'):
        value = {'arbitrary': -0.8, 'finite': -0.5, 'fixed': -0.25,
                 'given': -0.12, 'fix': -0.30}[word]
        if prev in ('a', 'an', 'any', 'some', 'all', 'each', 'every'):
            value -= 0.40
    elif whole_word and word == 'no':
        value = -0.36 if prev == 'is' else -0.16 if prev in (
            'are', 'be', "'s") else 0.0
    elif whole_word and word in ('one', 'two', 'three', 'four'):
        value = -0.5 if prev in QUANTIFIERS else -0.18 if prev in (
            'is', 'are', 'no', 'a', 'an') else 0.0
    elif whole_word and word == 'x':
        value = -0.42 if prev in QUANTIFIERS else -0.09
    return value


MATH_CONTEXT = set(
    'integer integers polynomial polynomials equation equations theorem '
    'proof lemma vector vectors subset subsets rational natural real '
    'complex prime triangle triangles'.split()
)
FOREIGN_QUANTIFIERS = {
    # Russian, French, German, Romance languages, Chinese, Japanese.
    'люб': -0.75, 'любой': -0.50, 'кажд': -0.68, 'каждого': -0.65,
    'каждый': -0.33, 'всех': -0.50, 'все': -0.15,
    'tout': -0.50, 'tous': -0.25, 'toute': -0.23, 'chaque': -0.25,
    'jede': -0.45, 'jeder': -0.22, 'cualquier': -0.43,
    'cada': -0.21, 'ogni': -0.37, 'todos': -0.22,
    '任何': -0.39, '每个': -0.31, '所有': -0.22, '全て': -0.48,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, history = '', ()
    else:
        _, previous, history = carry
    word = token.strip()
    value = lexical_response(token, previous)
    # Nearby mathematical notation changes ordinary indefinites into
    # explicit quantified entities. Keep only a sixteen-token window.
    if any(history):
        if token.startswith(' ') and word in ('a', 'an'):
            value -= 0.20
        elif word in QUANTIFIERS:
            value -= 0.23
        elif word in ('point', 'points', 'element', 'elements',
                       'given', 'fixed'):
            value -= 0.16
    if word in FOREIGN_QUANTIFIERS:
        value = FOREIGN_QUANTIFIERS[word]
    if word in ('∀', 'forall', 'ℕ'):
        value = -0.45
    mathematical = any(c in token for c in '$=^∈∀∃∑≤≥')
    mathematical |= word.lower() in MATH_CONTEXT
    history = (history + (mathematical,))[-16:]
    return (doc, token, history), float(value)

