"""Layer-0 MLP down-projection component 4260: a negative "quantifier / indefinite
article" detector.

It goes negative on the words that introduce an unspecified object: the articles
"a" / "an" (strongest right after "is", "be", "was", "exists", i.e. "X is a ...",
"there exists a ..."), the quantifiers "any", "some", "every", "each", "all", "exists",
and mathematical nouns such as "integer(s)", "number(s)", "element", "fixed", "arbitrary".
The size grows with how mathematical the surrounding text is (LaTeX marks, math words
in the last 40 tokens). Everything else is about 0.
"""

READS = ()

COPULAS = {" is", " be", " was", " are", " were", " being", "'s", " exists", " exist"}
QUANTIFIERS = {
    " any": -0.25, "Any": -0.3, " some": -0.33, " every": -0.25, " each": -0.22,
    " all": -0.14, " no": -0.06, " exists": -0.5, " exist": -0.42, " forall": -0.47,
}
MATH_NOUNS = {
    " integer", " integers", " numbers", " number", " element", " elements", " point",
    " points", " fixed", " arbitrary", " finite",
}
MATH_WORDS = {
    "let", "suppose", "prove", "theorem", "lemma", "proof", "integer", "integers",
    "exists", "number", "numbers", "element", "set", "function", "vector", "matrix",
    "field", "group", "space", "point", "vertex", "graph", "define", "choose", "assume",
}
MATH_MARKS = set("$\\^_{}=")
WINDOW = 40


def math_density(prefix):
    """How many of the last WINDOW tokens (same document) look mathematical."""
    count = 0
    t = prefix.position
    for i in range(t, max(-1, t - WINDOW), -1):
        if prefix.document_ids[i] != prefix.document_ids[t]:
            break
        s = prefix.token_strings[i]
        if MATH_MARKS & set(s) or s.strip().lower() in MATH_WORDS:
            count += 1
    return count


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    t = prefix.position
    same_doc = t > 0 and prefix.document_ids[t - 1] == prefix.document_ids[t]
    before = prefix.token_strings[-2] if same_doc else ""
    m = math_density(prefix)
    value = 0.0
    if word in (" a", " an"):
        if before in COPULAS:
            value = -0.45 - 0.07 * min(m, 15)
        else:
            value = -0.04 - 0.025 * min(m, 15)
    elif word in QUANTIFIERS:
        value = QUANTIFIERS[word] * (1 + 0.1 * min(m, 15))
    elif word in MATH_NOUNS:
        value = -0.3 * (1 + 0.1 * min(m, 15))
    return carry, float(value)

