"""A detector for mathematical symbols, exponents, and arrow-like operators.

Most ordinary text gets zero; this is not a general mathematics detector.
Arrow, relation, and power spellings have strengths measured on training text.
The first token of an exponent also fires. Greek letters and their names are
symbol cues, but adjacent Greek letters in recent text suggest Greek prose.
Space-prefixed dollar signs use recent math, PHP, or price cues. Only a bounded
text tail and the previous token are retained, and documents reset the state.
"""
import re
import unicodedata

READS = ()

OPERATORS = {
    '->': 0.80,
    '=>': 0.86,
    ':=': 0.62,
    '-->': 0.43,
    '<-': 0.48,
    '<=': 0.55,
    '>=': 0.46,
    '!=': 0.17,
    '→': 0.61,
    '⇒': 0.67,
    '≤': 0.82,
    '≥': 0.84,
    '∈': 0.82,
    '−': 0.65,
    '×': 0.33,
    '±': 0.44,
    '≈': 0.43,
    '≠': 0.49,
    '≡': 0.50,
    '∂': 0.46,
    '∀': 0.60,
    '∞': 0.35,
    '√': 0.22,
    '∅': 0.48,
    '′': 0.62,
    ')(': 0.40,
    '](': 0.31,
    '][': 0.17,
    '_{': 0.31,
    '}_{': 0.37,
    '\\(': 0.34,
