POWER_CONTEXT = re.compile(r'\^|[²³≤≥∈αβγδπ]')
PHP_CONTEXT = re.compile(
    r'->|=>|\$(?:this|[a-zA-Z_]\w{2,})|'
    r'\b(?:public|private|protected|echo|foreach|php|namespace)\b'
)
CLOSED_MATH = re.compile(r'\$[a-zA-Z](?:[{}_\\^][^$]*)?\$')
MONEY_CONTEXT = re.compile(
    r'\$[0-9]|\b(?:dollars|price|prices|pay|cost|shares|million|billion|tax|money)\b',
    re.I,
)
# Each pair is (space-prefixed spelling, spelling without an initial space).
GREEK_NAMES = {
    'alpha': (0.44, 0.24),
    'beta': (0.52, 0.30),
    'gamma': (0.65, 0.35),
    'delta': (0.48, 0.35),
    'epsilon': (0.51, 0.35),
    'theta': (0.42, 0.26),
    'lambda': (0.78, 0.38),
    'sigma': (0.71, 0.24),
    'omega': (0.50, 0.30),
    'phi': (0.50, 0.30),
    'psi': (0.50, 0.30),
    'mu': (0.26, 0.23),
    'pi': (0.10, 0.19),
    'tau': (0.40, 0.33),
    'rho': (0.40, 0.30),
    'eta': (0.25, 0.17),
}
LATEX_RELATIONS = {
    'in', 'le', 'leq', 'ge', 'geq', 'neq', 'subset', 'subseteq',
    'rightarrow', 'Rightarrow', 'implies', 'approx', 'equiv',
}


def response(s, previous, tail):
    token = s.strip()
    if token in OPERATORS:
        if token == '->' and s.startswith(' '):
            return 1.01
        return OPERATORS[token]
    if '->' in token:
        return 0.65
    if '=>' in token:
        return 0.82
    if '^' in token:
        if token.startswith((')', ']')):
            return 0.50
        if '{' in token or any(c.isalpha() for c in token):
