        if token == '{':
            return 0.79
        if not token:
            return 0.26
        if token == '(':
            return 0.35
        if token.isalpha() or token in ('-', '\\', '{\\'):
            return 0.48
    if token and all(c in '⁰¹²³⁴⁵⁶⁷⁸⁹⁺⁻' for c in token):
        return 0.77 if token == '³' else 0.63
    if len(token) == 1 and 'GREEK' in unicodedata.name(token, ''):
        if GREEK_WORD.search(tail):
            return -0.03
        return 0.50 if token.isupper() else 0.78
    if token == 'µ':
        return 0.55
    if token in ('$\\', '$('):
        return 0.84 if s.startswith(' ') else 0.62
    if s == ' $$':
        return 0.22
    if s == ' $':
        php = bool(PHP_CONTEXT.search(tail))
        if CLOSED_MATH.search(tail):
            return 0.26 if php and '\\' not in tail else 0.82
        if php:
            return 0.02
        if any(c in tail for c in '{}='):
            return 0.78 if POWER_CONTEXT.search(tail) else 0.58
        if MONEY_CONTEXT.search(tail):
            return 0.15
        return 0.34
    if token.lower() in GREEK_NAMES:
        pair = GREEK_NAMES[token.lower()]
        return pair[0] if s.startswith(' ') else pair[1]
    # Some TeX commands are split across tokens.
    if token == 'q' and previous in ('le', 'ge', 'ne'):
        return 0.75
    if token == 'ambda' and previous.endswith('l'):
        return 0.72
    if token == 'fty' and previous == 'in':
        return 0.65
    if token == '=lambda':
        return 0.97
    if token in LATEX_RELATIONS and previous.endswith('\\'):
        return 0.58
    if token.lower() in {
        'suggest', 'suggests', 'suggested', 'suggesting',
        'imply', 'implies', 'implied', 'implying',
    }:
        return 0.26
    if token.lower() in {'formula', 'formulas'}:
        return 0.40
    if token.lower() in {'matrix', 'matrices', 'algebra', 'cubic'}:
        return 0.28
    if len(token) == 1 and ord(token) > 127:
        # Unlisted mathematical operators share a moderate positive response.
        if unicodedata.category(token) == 'Sm':
            return 0.43
        if 'SUBSCRIPT' in unicodedata.name(token, '') and token.isdigit():
            return -0.10
    if re.fullmatch(r'[+*=!/-]?\(', token):
        return 0.15 if token != '(' else (0.02 if s.startswith(' ') else 0.07)

    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        start = len(prefix.text_prefixes[-2]) if prefix.position else 0
        carry = (doc, '', '', start)
    _, previous, tail, start = carry
    s = prefix.token_strings[-1]
    full = None
    if '\ufffd' in s:
        # Complete a character whose UTF-8 bytes crossed a token boundary.
        full = prefix.text_prefixes[-1]
        s = full[-len(s):]
    value = response(s, previous, tail)
    tail = (tail + s)[-1000:] if full is None else full[max(start, len(full)-1000):]
    return (doc, s, tail, start), float(value)

programs.haiku:
"""Math symbols inside English text.

The component fires on mathematical notation written into English prose or LaTeX:
arrows (->, =>, →), relation signs (≤, ∈, −), exponent markers (x^2, the 2 after ^),
Greek letters used as variables (α, β, δ), and the $ that opens an inline formula.
Greek letters and the replacement character fire only when the surrounding text is
Latin script, so the same symbols in Greek or Japanese text stay near zero.
"""
import unicodedata

READS = ()

ARROWS = {"->", "=>", "→", "⇒", "↦", "⟶", "⟹", "rightarrow"}
STRONG_RELATIONS = {"≤", "≥", "∈"}
RELATIONS = {"−", ":=", "<=", "≈", "±", "∀", "∃"}
SUPERSCRIPT_DIGITS = {"²", "³", "¹"}
LATIN_WINDOW = 15      # tokens of context looked back at
LATIN_MIN = 0.7        # share of ASCII letters among letters and other non-space characters


def is_greek(s):
    return bool(s) and unicodedata.name(s[0], "").startswith("GREEK")


def latin_context(prev_tokens):
    """True when the recent text is mostly Latin-script letters (English prose or LaTeX)."""
    text = "".join(prev_tokens)
    ascii_letters = sum(1 for c in text if c.isascii() and c.isalpha())
    other = sum(1 for c in text if not c.isascii() and not c.isspace())
    return ascii_letters >= LATIN_MIN * max(1, ascii_letters + other)


def weight(prev, prev_tokens, token):
    s = token.strip()
    if s in ARROWS:
        return 0.85
    if s in STRONG_RELATIONS:
        return 0.85
    if s in RELATIONS:
        return 0.6
    if s in SUPERSCRIPT_DIGITS:
        return 0.75
    if s.isdigit() and prev.rstrip().endswith("^"):      # the 2 in x^2
        return 0.9
    if s.startswith("^") or s.endswith("^"):              # the ^ that starts an exponent
        return 0.6
    if is_greek(s):                                       # Greek letter as a variable
        if not latin_context(prev_tokens):
            return 0.0
        return 0.8 if token[:1] == " " else 0.6
    if token == " $\\":
        return 0.8
    if token == " $" and prev.strip().isalpha():          # "that $x": math after a prose word
        return 0.55
    if s == "�" and latin_context(prev_tokens):
        return 0.25
    is_math_symbol = any(not c.isascii() and unicodedata.category(c) == "Sm" for c in s)
    if is_math_symbol and latin_context(prev_tokens):
        return 0.5
    return 0.0


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    prev = toks[-2] if len(toks) > 1 else ""
    prev_tokens = toks[-LATIN_WINDOW - 1:-1]
    return None, weight(prev, prev_tokens, toks[-1])

programs.luna:
"""Predict the component's sparse responses with a small formal-notation heuristic.
Most positions stay near its average activation; notation cues get a modest boost.
"""
import unicodedata

READS = ()

ARROWS = set("→←↔⇒⇐↦⟶⟵⟷")
MATH_MARKS = set("δΔμωΩλπθσφψαβγ∈∉≤≥≠≈≡×÷±−²³¹")
TEX_COMMANDS = {"in", "to", "times", "le", "ge", "neq", "alpha",
                "beta", "delta", "mu", "omega", "pi"}

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    doc = prefix.document_ids[-1]
    tail = "" if carry is None or carry[0] != doc else carry[1]

    cue = 0.0
    if word in {":=", "=>", "->", "<="}:
        cue = 0.7
    elif any(ch in ARROWS or ch in MATH_MARKS for ch in token):
        cue = 0.7
    elif any(unicodedata.name(ch, "").startswith("GREEK ")
             for ch in token):
        cue = 0.7
    elif word == "](":
        cue = 0.4
    elif word == "Formula":
        cue = 0.45
    elif "$" in token:
        cue = 0.45
    elif "\ufffd" in token:
        cue = 0.25
    elif tail.rstrip().endswith("^") and word.isdigit():
        cue = 0.7
    elif "^" in token and token.rstrip()[-1:].isdigit():
        cue = 0.7
    elif tail.endswith("\\") and word in TEX_COMMANDS:
        cue = 0.6

    prediction = 0.00407 + 0.5 * cue
    return (doc, (tail + token)[-24:]), float(prediction)

programs.sol:
"""A word-level detector for 'which' and related ways of selecting a set.

The strongest response is to English 'which', especially at a clause boundary.
Some prepositions reduce it, most of all 'in'. Object/possessive relatives, choice
words and several translated relatives produce smaller pulses. 'The following'
and 'how many' are recognized as phrases, as are split question-word
prefixes and completions. Everything else is silent.
"""

READS = ()

CHOICE_WORDS = {
    'both': 0.85, 'either': 0.82, 'neither': 0.67, 'whether': 0.8,
    'whichever': 3.2, 'wherein': 0.68, 'whereby': 1.16,
}
# Relative/choice pronouns, grouped by language rather than token identity.
ROMANCE_RELATIVES = {
    'qui': 0.85, 'dont': 0.4,
    'quel': 1.1, 'quelle': 1.5, 'quels': 1.1, 'quelles': 1.5,
    'qual': 1.1, 'quale': 1.8, 'quali': 1.8, 'cui': 1.1,
    'cual': 2.1, 'cuál': 2.1, 'cuales': 2.4, 'cuáles': 2.4,
}
OTHER_RELATIVES = {
    'deren': 0.55, 'wel': 1.85, 'yang': 0.54,
    'التي': 1.45, 'الذي': 1.5, 'والتي': 3.2,
    '哪': 3.6, '哪个': 3.4, '哪些': 2.2, 'どの': 1.46,
    '其中': 0.59, '以下': 0.5,
}


def which_response(word, previous, at_start):
    if at_start:
        return 10.0 if word[0].isupper() else 6.6
    value = 5.2 + (0.95 if word[0].isupper() else 0.0)
    p = previous.strip().lower()
    if previous == ',':
        value += 0.74
    elif ',' in previous:
        value += 0.33
    elif p in ('(', '[', '{', '"', '“', '##', '###'):
        value += 0.74
    elif p.isdigit():
        value -= 0.43
    elif p == 'in':
        value -= 1.53
    elif p == 'of':
        value += 0.45
    elif p in ('at', 'by'):
        value -= 0.6
    elif p in ('after', 'during'):
        value -= 1.07
    elif p in ('for', 'to', 'with', 'within', 'into'):
        value -= 0.25
    elif p in ('on', 'through', 'under'):
        value += 0.36
    elif p in ('and', 'but', 'or'):
        value += 0.67
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    start = carry is None or carry[0] != document
    previous = '' if start else carry[1]
    before_previous = '' if start else carry[2]
    token = prefix.token_strings[-1]
    word = token.strip()
    w = word.lower()
    p = previous.strip().lower()
    comma = ',' in previous
    value = 0.0
    # Some relative pronouns arrive in two pieces; recognize the completion.
    continuation = bool(token) and not token[0].isspace()
    if continuation and p == 'wh' and w in ('ich', 'om', 'ose', 'ichever'):
        if w == 'ich':
            value = 6.0
        elif w == 'ose':
            value = 3.3 if previous.strip()[0].isupper() else 2.4
        else:
            value = 3.2
    elif continuation and p == 'wel' and w in ('che', 'cher', 'ches', 'chen'):
        value = 2.4
    elif continuation and p == 'след' and w == 'ующ':
        value = 1.0
    elif w == 'wh':
        value = 1.1 if word[0].isupper() else 0.8
    elif w == 'of' and p == 'which':
        value = 1.1 if previous.strip()[0].isupper() else 0.5
    elif w == 'which' or w == '.which':
        value = which_response(word.lstrip('.'), previous, start)
    elif w == 'whom':
        value = 3.2 + (0.6 if comma else 0.0)
        if p == 'in':
            value -= 0.85
    elif w == 'whose':
        value = 2.2 + (0.5 if comma else 0.0)
    elif w == 'who':
        value = 0.85 if word[0].isupper() else 0.4
        if comma:
            value = 0.7
        elif p in ('people', 'those', 'patients', 'students', 'individuals'):
            value = 0.02
    elif w in CHOICE_WORDS:
        value = CHOICE_WORDS[w]
    elif w == 'following' and p == 'the':
        value = 1.5 if before_previous.strip().lower() == 'of' else 0.96
    elif w == 'many' and p == 'how':
        value = 1.0
    elif w.startswith('котор'):
        value = 2.3
    elif w.startswith('welch') or w == 'kter':
        value = 2.4
    elif w.startswith('który') or w in ('która', 'które'):
        value = 2.2
    elif w in ROMANCE_RELATIVES:
        value = ROMANCE_RELATIVES[w]
    elif w in OTHER_RELATIVES:
        value = OTHER_RELATIVES[w]
        if w == 'wel' and word[0].isupper():
            value = 0.6
    return (document, token, previous), float(value)

programs.luna:
"""Estimate the component from relative/interrogative and choice words.

Its largest response is to “which”; other relative words, especially
“whom” and “whose,” have smaller responses. Paired-choice words also get
modest estimates. This is a small lexical approximation, not a grammar parser.
"""
READS = ()
BASE = 0.0084

RELATIVE_WORDS = {
    "who": 0.45, "whom": 3.2, "whose": 2.55,
    "qui": 0.9, "cui": 1.4, "quel": 1.0,
    "welche": 2.43,
    "который": 2.4, "которого": 2.0, "которым": 2.3,
    "которые": 1.93, "которых": 3.0, "которой": 2.6,
    "которое": 2.18, "которая": 2.16,
    "哪些": 2.3, "哪": 4.5, "التي": 1.4,
}
OTHER_MARKERS = {
    "both": 0.86, "either": 0.83, "neither": 0.68,
    "whether": 0.80, "following": 0.85,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    word = token.casefold()
    if word == "which":
        value = 6.3 if token[:1].isupper() else 5.4
    elif word in RELATIVE_WORDS:
        value = RELATIVE_WORDS[word]
    elif word in OTHER_MARKERS:
        value = OTHER_MARKERS[word]
    else:
        value = BASE
    return None, float(value)

programs.haiku:
"""Fires on the preposition "of" (and Romance de/di). Strength depends on the noun
before it: strongest for "X of" where X names a kind, amount, part or version of
something (kind of, type of, cup of, pounds of, version of); weakest for "of" after
abstract or verbal nouns (analysis of, number of, consist of, review of)."""

READS = ()

MEASURE_NOUNS = {
    "kind", "kinds", "type", "types", "sort", "version", "cup", "cups", "lot",
    "lots", "amount", "part", "pounds", "plenty", "months", "way", "tracks",
    "system", "bit", "piece", "piece", "series", "number_",
}
ABSTRACT_NOUNS = {
    "analysis", "dynamics", "number", "consist", "relaxation", "review",
    "darkness", "morning", "heart", "nature", "job", "use",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word == "of":
        before = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
        if before in MEASURE_NOUNS:
            return None, 2.0
        if before in ABSTRACT_NOUNS:
            return None, 0.2
        return None, 0.8
    if word in ("de", "di"):
        return None, 0.3
    return None, 0.0

programs.sol:
"""A lexical DEV/development signal, mostly negative and near zero otherwise.

The abbreviation dev is strongest. Inflected develop words, translations of
'development', and some similar spellings receive smaller responses. We handle
split words, the phrase 'development of', and completed Japanese byte-split
characters. This omits the component's many small background responses.
"""
READS = ()

DEVELOP_SUFFIXES = {
    '': 4.85, 'ed': 3.65, 'ing': 4.7, 's': 4.25,
    'ment': 4.3, 'ments': 3.1, 'mental': 2.4, 'er': 3.9, 'ers': 4.3,
}
SPLIT_SUFFIXES = {'ed': 2.5, 'ing': 3.7, 'er': 3.0,
                  'ers': 3.3, 's': 2.8, 'ment': 3.0}
CHARACTER_PIECES = {
    '发': 2.2, '發': 1.9, '髮': 2.0, '発': 1.65,
    '开': 1.0, '開': 1.0, '展': 0.68, '设备': 0.68,
    '발': 1.3, '개발': 3.1, '개': 0.8,
}


def strength(token):
    word = token.lstrip(' \t\r\n._-/(')
    low = word.lower()
    capital = word[:1].isupper()
    spaced = token[:1].isspace()
    if low == 'dev':
        if capital:
            return 5.4 if spaced else 6.3
        if token.startswith('/'):
            return 8.3
        if token.startswith('('):
            return 5.0
        return 6.3 if spaced or token.startswith('.') else 7.4
    if low.startswith('develop'):
        ending = low[7:]
        value = DEVELOP_SUFFIXES.get(ending, 3.5)
        if capital and ending in {'ment', 'er'}:
            value += 0.35 if spaced else 0.8
        return value
    if low.startswith('velop'):
        return 3.85 if low.startswith('velopment') else 2.3
    if low in {'develo', 'devel', 'deve'}:
        return {'develo': 4.8, 'devel': 3.3, 'deve': 1.1}[low]
    for stem, value in [('devic', 1.5), ('deviat', 2.1), ('devil', 2.8),
                        ('devon', 2.2), ('devot', 1.2), ('devis', 2.0),
                        ('delet', 0.7), ('evol', 1.0)]:
        if low.startswith(stem):
            return value
    if low in {'ev', 'rev', 'env', 'deriv', 'derive'}:
        return 1.0
    if low == 'ogenesis':
        return 0.85

    # Development translations and related character spellings.
    if word.startswith(('开发', '開發')):
        return 3.5 if len(word) > 2 else 6.0
    if '发展' in word or '發展' in word:
        return 1.9
    if '研发' in word or '发育' in word:
        return 2.0
    if word in CHARACTER_PIECES:
        return CHARACTER_PIECES[word]
    if low.startswith('entwick'):
        return 2.1 if low.endswith('lung') else 3.4
    if low.startswith('dévelop'):
        return 2.9 if low.endswith('ment') else 2.2
    if low.startswith('desarroll'):
        return 1.55 if low.endswith('o') else 2.0
    if low.startswith(('desenv', 'развит', 'развив', 'разв')):
        return 1.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    tail = carry[1] if same_doc else ''
    token = prefix.token_strings[-1]
    low = token.lower()
    value = strength(token)
    if not token[:1].isspace():
        if tail.lower().endswith('develop'):
            value = SPLIT_SUFFIXES.get(low, value)
        if tail.lower().endswith('de') and low == 'velo':
            value = 2.85
        if tail.lower().endswith('develo'):
            value = {'pment': 3.7, 'ping': 1.1}.get(low, value)
        if token == '발' and tail.endswith('개'):
            value = 4.7
    if low == ' of' and tail.lower().endswith('development'):
        value = 1.65
    # A byte fragment cannot be interpreted until the character is complete.
    if token == '\ufffd' and same_doc:
        complete = prefix.text_prefixes[-1][-1:]
        if complete == '発':
            value = 2.85 if tail.rstrip('\ufffd').endswith('開') else 1.65
        if complete != '\ufffd':
            tail = tail.rstrip('\ufffd')
            token = complete
    return (doc, (tail + token)[-24:]), float(-value)

