"""Recognize the develop/development word family, not every word beginning
with the same letters. A weaker response covers a few other de-v words."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lstrip(" .").casefold()
    if token == "dev" or token.startswith("develop"):
        return None, -4.8
    if token.startswith(("devi", "devic", "devot")):
