programs.sol:
"""Opening punctuation at text boundaries.

A parenthesis or bracket just after a newline has a large positive response.
Indentation weakens it; inline punctuation and grammatical words give smaller
responses. Delimiters attached to ordinary words are mostly inactive. Paths,
comment stars and other line-formatting marks also receive smaller responses.
This summarizes the observed preference for beginning a formatted region.
"""
READS: tuple[str, ...] = ()
CONTROL_WORDS = {'if', 'for', 'while', 'switch', 'catch', 'except', 'return'}
FUNCTION_WORDS = {'and', 'or', 'is', 'are', 'was', 'be', 'by', 'as', 'the', 'to', 'of'}


def activation(s, previous, line_start, first):
    u = s.lstrip()
    if not u:
        return 0.0
    c = u[0]
    spaced = len(s) != len(u)
    newline = '\n' in previous
    whitespace = bool(previous) and previous[-1].isspace()
    word = previous.strip()
    last = word[-1:]
    punctuation = bool(last) and not last.isalnum()
    index = next((i for i, ch in enumerate(u) if ch in '([{'), -1)
    if index >= 0:
        opening, tail = u[index], u[index + 1:]
        if first:
            return 0.65
        if previous.endswith('\\n'):
            return 1.8
        if newline:
            if opening == '{':
                return 0.7 if '\n' in s else 1.7
            if index > 0 or '\n' in s:
                return 1.7
            if tail and tail[0].isalpha():
                return 4.0 if tail[0].isupper() else 2.9
            return (2.7 if spaced else 3.7) if not tail else 2.0
        if index > 0:
            return 0.4
        if line_start and (spaced or whitespace):
            if '\n' in s:
                return 0.65 if opening == '{' else 1.7
            return 1.5 if opening == '{' else (2.1 if spaced else 3.4)
        if spaced:
            if '\n' in s:
                return 0.0 if opening == '{' else 0.43
            if whitespace:
                return 1.3
            if punctuation:
                return 1.1 if opening == '(' else 0.65
            if word in CONTROL_WORDS:
                return 1.0
            if word in FUNCTION_WORDS:
                return 0.6
            return 0.4 if opening == '(' else 0.25
        if whitespace:
            return 1.4
        if punctuation:
            return 0.6 if opening == '(' else 0.25
        if len(tail) > 2 and tail[0].isalpha():
            return 0.5 if tail[0].isupper() else 0.3
        return -0.1 if opening == '{' else 0.0

    if s == '<tool_call>':
        return 1.0
    if c == '*' and '\n' not in s:
        return 1.1 if newline else (0.6 if whitespace else 0.15 if spaced else 0.0)
    if c == '/' and any(ch.isalpha() for ch in u):
        if u in {'/test', '/tests'} and whitespace:
            return 2.0
        return 0.9 if newline else 0.0
    if c in '（【《「『〈〔［｛':
        if newline:
            return 3.2 if c == '（' else 1.3
        return 0.2
    if c == '<':
        if first or u.startswith('<|') or u in {'<tool_response>', '<thinking>'}:
            return 0.0
        return 0.9 if line_start else 0.0
    if u in {'✓', '✔', '✅'}:
        return 0.67
    if newline:
        if len(u) > 1 and len(set(u)) == 1 and c in '-=_~+#':
            return 1.0
        if c == '^':
            return 2.0
        if c in '.\\=_~—–':
            return 0.95
        if c in "'\"“‘$%!@|>+&:«":
            return 0.6
        return -0.03 if c.isalnum() else 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, previous, line_start = (doc, '', True) if first else carry
    s = prefix.token_strings[-1]
    value = activation(s, previous, line_start, first)
    if '\n' in s:
        line_start = not s.rsplit('\n', 1)[1].strip()
    elif s.strip():
        line_start = False
    return (doc, s, line_start), float(value)

programs.haiku:
"""Opening brackets that start a line or stand apart from a preceding word.

Layer-0 MLP unit 4266 writes an "opening bracket here" signal into the residual stream.
It is strongest when a bracket such as "(", "[", "{" or "（" opens a line: most of all
right after a line break that ends a sentence or item (about 3.6), less after a plain
line break or indentation (about 2.5). Mid-line it is weak after punctuation such as
"=", ",", ":" (about 0.5-1) and near zero when the bracket is glued to a preceding word,
as in "f(x)". A spaced " (" is weaker than a glued "(" at the line start. Path roots at
the line start (/usr, /test, /workspace) also fire. Everything else is about 0.
"""

READS = ()

OPENERS = "([{<（【《『"
PATH_ROOTS = {"/test", "/usr", "/workspace", "/root", "/local"}
DIVIDERS = {"===", "---", "✓", "*", " *"}


def _is_opener(token):
    body = token.lstrip(" ")
    return bool(body) and body[0] in OPENERS and len(body) <= 3 and not token.endswith("\n")


def _prev_kind(prefix):
    """What precedes this token: 'newline_after_punct' (a line break after a sentence or item
    ends), 'ws' (a line start, indentation or document start), 'punct' (mid-line punctuation
    or a symbol) or 'word' (a letter or digit)."""
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return "ws"
    prev = prefix.token_strings[-2]
    body = prev.rstrip(" \t\r\n\xa0")
    if not body:
        return "ws"
    if body != prev:
        return "newline_after_punct" if not body[-1].isalnum() and "\n" in prev else "ws"
    if body[-1].isalnum() or body[-1] == "_":
        return "word"
    return "punct"


LEVEL = {
    ("glued", "ws"): 2.5, ("glued", "newline_after_punct"): 3.6,
    ("glued", "punct"): 0.4, ("glued", "word"): 0.0,
    ("spaced", "ws"): 1.5, ("spaced", "newline_after_punct"): 2.5,
    ("spaced", "punct"): 0.9, ("spaced", "word"): 0.4,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    kind = _prev_kind(prefix)
    if _is_opener(token):
        glue = "spaced" if token.startswith(" ") else "glued"
        return carry, LEVEL[(glue, kind)]
    if token in PATH_ROOTS and kind in ("ws", "newline_after_punct"):
        return carry, 1.4
    if token in DIVIDERS and kind in ("ws", "newline_after_punct"):
        return carry, 1.0
    return carry, 0.0

programs.sol:
"""Plural-looking spellings, especially in French and other Romance languages.

Recent completed function words provide language evidence. This gates generic
-s endings, which are much weaker in English. Distinctive Romance endings and
Russian plural adjective endings also respond. There are also rules for
Italian -i, Greek -ς and Arabic -ات; Cyrillic -ой gets a positive value.
This is a spelling heuristic, not a grammatical parser: 'pas', 'plus' and
'sont' have separate responses too. State resets at document boundaries.
"""
import re

READS = ()
FRENCH = set(('le une du au aux les dans pour avec sur est ce ces qui pas '
              'nous vous ils elle elles mais sont avait été être plus et '
              'à lui ne il').split())
IBERIAN = set(('el los las una del al por con pero como sus su para unos '
              'unas todos todas entre os uma não são com dos das pela '
              'pelo na no seus suas é ao também').split())
ITALIAN = set(('il gli della delle dei dello che sono per non nella nel '
              'alla alle degli').split())
SHARED = set('la de que en se un l d'.split())
OTHER = set(('the and of to that with is this it for from are have was '
             'were as be by not der die das und den dem ein eine ist mit '
             'von zu').split())
FRENCH_ENDINGS = ('ées', 'aires', 'ières', 'ères', 'èmes', 'êmes', 'iques',
                  'euses', 'ifs', 'eaux', 'aux', 'eux')
IBERIAN_ENDINGS = ('ados', 'adas', 'idos', 'idas', 'adores', 'adoras',
                   'aciones', 'iciones', 'uciones', 'idades', 'ências',
                   'ções', 'ões', 'icos', 'icas', 'ivos', 'ivas', 'ías')
ENDING_EXCEPTIONS = set(('dans mais sans alors es is as us this thus was has his '
                'its does yes news always perhaps deux').split())
ENGLISH_SHARED_ENDINGS = set('s is us ions ations ens ants its ets ons'.split())
PLURAL_DETERMINERS = set('ces mes tes ses nos vos'.split())
PERSONAL_PRONOUNS = set('nous vous'.split())
PLURAL_PRONOUNS = set('ils elles leurs'.split())
PLURAL_EXPRESSIONS = set(('autres quelques plusieurs tous toutes sus tus '
                          'seus suas todos todas otros otras').split())
PORTUGUESE_ARTICLES = set('os as dos das'.split())
ITALIAN_PLURAL_WORDS = set('gli dei delle degli suoi loro'.split())
PARTS = re.compile(r'[A-Za-zÀ-ɏ]+|[^A-Za-zÀ-ɏ]+')


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        scores, pending, previous = [0.0] * 4, '', ''
    else:
        scores = [x * 0.97 for x in carry[1]]
        pending, previous = carry[2:]
    # Count completed words, not unspaceds: 'la' in 'lambda' is not an article.
    for part in PARTS.findall(token):
        if part[0].isalpha():
            pending = (pending + part.lower())[-40:]
        else:
            for k, words in enumerate((FRENCH, IBERIAN, ITALIAN, OTHER)):
                scores[k] += float(pending in words)
            if pending in SHARED:
                for k in range(3):
                    scores[k] += 0.15
            if any(c in pending for c in 'éèêëàùœ'):
                scores[0] += 0.3
            if any(c in pending for c in 'ñãõáíóú'):
                scores[1] += 0.3
            pending = ''
    total = sum(scores) + 1.0
    western = max(0.0, ((scores[0] + scores[1]) / total - 0.3) / 0.7)
    french, italian = scores[0] / total, scores[2] / total
    word = token.strip().lower()
    unspaced = bool(token and not token[0].isspace())
    start = not unspaced or not previous or not previous[-1].isalpha()
    latin = word.isalpha() and all(
        'a' <= c <= 'z' or '\u00c0' <= c <= '\u024f' for c in word)
    value = 0.001
    if latin and word.endswith(('s', 'x')) and not word.endswith('ss'):
        if start and word == 'les':
            value = -1.5 if token.strip().islower() else -1.2
        elif start and word in {'los', 'las'}:
            value = -1.15 if token.strip().islower() else -0.6
        elif start and word == 'des':
            value = -0.15 - 0.65 * western - 1.15 * french
        elif start and word in PLURAL_DETERMINERS:
            value = -0.15 - 0.8 * western - 0.7 * french
        elif start and word in PERSONAL_PRONOUNS:
            value = -0.15 - 0.3 * french
        elif start and word in PLURAL_PRONOUNS:
            value = -0.65 - 0.5 * western
        elif start and word in PLURAL_EXPRESSIONS:
            value = -0.5 - 0.5 * western
        elif start and word in PORTUGUESE_ARTICLES:
            value = -1.2 * western
        elif start and word in {'pas', 'plus'}:
            value = -0.1 - 0.6 * western - 0.35 * french
        elif start and word in ENDING_EXCEPTIONS:
            value = 0.0
        elif word.endswith(IBERIAN_ENDINGS):
            value = -0.8 - 0.75 * western
        elif word.endswith(FRENCH_ENDINGS):
            value = -0.35 - 1.5 * french
        elif word == 'ux':
            value = -0.45 - 0.6 * french
        elif word.endswith('x'):
            value = 0.0
        elif unspaced and word in ENGLISH_SHARED_ENDINGS:
            value = -0.03 - 0.8 * western - 0.6 * french
        else:
            value = -0.04 - (1.7 if unspaced else 0.95) * western
    elif latin and unspaced and word.endswith('i'):
        value = -0.02 - 1.25 * italian
    if start and word in ITALIAN_PLURAL_WORDS:
        value = -0.55
    if start and word in {'i', 'le'}:
        value = -italian
    if start and word == 'sont':
        value = -0.52
    if unspaced and word.isalpha():
        if word.endswith(('ые', 'ых', 'ные', 'ных', 'кие', 'ких',
                          'шие', 'ших', 'ыми')):
            value = -0.8
        elif word.endswith(('ющие', 'ющих', 'ющихся')):
            value = -0.6
        elif word.endswith(('ие', 'их', 'ими')):
            value = -0.17
        elif word.endswith(('ами', 'ями', 'ах', 'ях')):
            value = -0.25
        elif word.endswith('ой'):
            value = 0.15
        elif word.endswith(('ное', 'ного')):
            value = -0.18
        elif word.endswith('ς'):
            value = -0.28
        elif word.endswith('ات'):
            value = -0.3
    return (doc, scores, pending, token), float(value)

"""Approximate a short-context response to English apostrophe-s patterns.
Selected scientific nouns, thinking verbs and institutional/holiday titles
receive strong positive values just after 's; other completions are weaker.
Bare s-final possessive apostrophes get a scaled response. There are related
rules for 'me' plus thinking verbs and hyphen-leading tokens after final s.
The suffix in "let's" itself gets a small negative value. Context resets at
document boundaries. This captures response hotspots, not all lexical or
multilingual variation of the component.
"""
READS = ()
EPONYMS = {'law', 'theorem', 'lemma', 'algorithm', 'rule'}
RELATIONS = {'formula', 'disease', 'principle'}
OFFICIAL_TITLES = {'Office', 'Attorney', 'University', 'Library'}


def after_s(token):
    word = token.strip()
    lower = word.lower()
    if lower in EPONYMS or lower == 'laws':
        return 1.25
    if lower in RELATIONS:
        return 0.85
    if lower == 'equation':
        return 0.50
    if word == 'Eve':
        return 2.00
    if word == 'Day':
        return 1.50
    if word == 'Hospital':
        return 1.30
    if word in OFFICIAL_TITLES:
        return 0.90
    if word in {'College', 'School', 'Department'}:
        return 0.65
    if word in {'Medical', 'Health'}:
        return 0.45
    if word in {'Magazine', 'Guide'}:
        return 1.00
    if word in {'Journal', 'Quarterly'}:
        return 0.65
    if lower in {'edge', 'side', 'place'}:
        return 0.75
    if lower == 'equity':
        return 0.65
    if lower == 'hear':
        return 0.90
    if lower in {'see', 'say', 'denote', 'call', 'know'}:
        return {'see': 1.25, 'say': 1.05, 'denote': 0.95,
                'call': 0.85, 'know': 0.80}[lower]
    if lower in {'got', 'it'}:
        return 0.90
    if lower in {'suppose', 'assume', 'understand'}:
        return 0.55
    if lower in {'book', 'edition', 'guide', 'wife', 'mother',
                 'last', 'best', 'job', 'role', 'supervisor'}:
        return 0.50
    if lower in {'check', 'define', 'name', 'first', 'own', 'what', 'been'}:
        return 0.32
    if lower in {'not', 'just', 'still', 'working'}:
        return 0.0
    if any(c.isalpha() for c in word):
        return 0.30 if word.istitle() else 0.12
    return 0.08


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word, prev = token.strip().lower(), previous.strip().lower()
    value = 0.0
    if prev in {"'s", '’s'}:
        value = after_s(token)
    elif prev in {"'", '’'} and len(prefix.token_strings) >= 3:
        before = prefix.token_strings[-3].strip().lower()
        if prefix.document_ids[-3] == doc and before.endswith('s'):
            value = 0.65 if word == 'equity' else 0.60 * after_s(token)
    elif prev.endswith('s') and token.startswith('-'):
        value = 0.15
        if token in {'-on', '-Co'}:
            value = 0.85
        elif token == '-node':
            value = 0.45
    elif prev == 'me':
        if word in {'see', 'know'}:
            value = 0.53
        elif word == 'denote':
            value = 0.35
        elif word in {'think', 'check', 'define', 'assume', 'suppose'}:
            value = 0.16
        elif word in {'try', 'write', 'use', 'take', 'do', 'look', 'find'}:
            value = 0.08
    if word in {"'s", '’s'} and prev == 'let':
        value = -0.15
    return (doc, token), float(value)

programs.haiku:
"""Draft: the component fires on the word right after a possessive 's (Faraday's law, Let's see).

It is quiet almost everywhere else. The strongest responses come when the word after the
apostrophe-s completes a familiar phrase: "Let's see/say/denote", "New Year's Eve", "Faraday's law".
Predictions are the average activation of each case (rounded), so the program says how big each
response is, not only where it occurs.
"""
READS = ()

POSSESSIVE = {"'s", "’s"}
LET_VERBS = {" see", " say", " denote"}
PHRASE_HEADS = {" law", " Law", " Eve", " Day", " Office", " Attorney", " Hospital", " algorithm", " call"}


def step(carry, prefix, upstream):
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2]
    if prev in POSSESSIVE:
        if cur in LET_VERBS or cur in PHRASE_HEADS:
            return carry, 1.3
        return carry, 0.15
    if prev == " me" and cur in LET_VERBS:
        return carry, 0.5
    if cur in PHRASE_HEADS:
        return carry, 0.12
    return carry, 0.0

"""Fires on the word right after a degree adverb (much, far, a lot, way, very, even, just, a bit, ...), most
strongly when that word is a comparison word: much MORE, far BETTER, way TOO, a lot EASIER, much OTHER."""
DEGREE = {" much", " lot", " far", " way", " very", " even", " just", " bit", " right", " little", " Far", " Just", " Right", " exactly", " pretty", " quite", " straight", " whole", " well", " still", " rather", " ever"}
COMPARISON = {" more", " less", " too", " better", " worse", " easier", " harder", " higher", " lower", " smaller", " larger", " bigger", " greater", " simpler", " stronger", " faster", " further", " longer", " shorter", " farther", " other", " different", " same", " similar", " like", " before", " after", " later", " now", " best", " first"}

READS = ()

def step(carry, prefix, upstream):
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    prev, cur = prefix.token_strings[-2], prefix.token_strings[-1]
    if prev not in DEGREE:
        return None, 0.0
    return None, 3.0 if cur in COMPARISON else 0.2

programs.sol:
"""A lexical alarm and vigilance signal, not a test of actual danger.

Give large responses to explicit alarms and warnings, smaller responses to
watching, detection, fear, and protection. Recognize common Chinese terms,
split English words, and the phrases 'early warning/detection/diagnosis',
'aware of', 'worried about', and 'sensitive to'. Otherwise predict zero.
"""
import re

READS = ()

VIGILANCE = set('detect detecting detection guard guards guarded guarding '
                'surveillance suspicion warrant precaution safeguard monitoring '
                'wary watchdog'.split())
SENSING = set('detected detector watch watches watcher sensor sensors monitor '
              'monitored sensitive awareness diagnosis diagnostic fear feared '
              'afraid worried worry threat threats suspicious judgment danger '
              'dangers'.split())
PREVENTION = set('protect protecting protective prevent prevents preventing '
                 'prevention security cybersecurity watching watched guardian '
                 'vulnerable dangerous fears startled sensing inspector '
                 'detective patrol hazard hazardous eslint'.split())
AWARENESS = set('attention safety risk risks concern concerns concerned '
                'sensitivity threatened threatening notice noticed notify '
                'notified notification notifications recognition aware screening '
                'defend defense protection suspect forecast prediction careful '
                'audit firewall lint'.split())

CHINESE = {}
for strength, words in (
    (8.0, '警'), (6.4, '预警'), (5.2, '报警'), (4.7, '警惕'),
    (4.0, '戒'), (3.6, '警告 警示'), (2.2, '警方 警察 公安 防范'),
    (1.3, '防 防止 预防 防护 提醒 监控 监测 排查 '
          '谨慎 担心 敏 敏感 诊断'),
    (0.95, '检测 保护 恐 怕 危险 诊 診 检 檢 卫 衛 险 險 疑 恐惧 ⚠'),
    (0.6, '安全 通知 注意 守 发现 告知 觉 覺 醒 风险 报 報'),
):
    CHINESE.update(dict.fromkeys(words.split(), strength))


def lexical(raw):
    word = raw.strip().strip('_-./').lower()
    if word in CHINESE:
        return CHINESE[word]
    if word in {'alert', 'alerts'}:
        return 4.3 if raw.startswith(' ') else 3.7
    if word in {'alarm', 'alarms'}:
        return 4.0 if raw.startswith(' ') else 2.5
    if word in {'alerted', 'alerting'}:
        return 3.0
    if word == 'alarming':
        return 1.5
    if word == 'warning':
        if raw.strip() == 'Warning':
            return 3.0
        return 3.4 if raw.startswith(' ') else 2.3
    if word == 'warnings':
        return 2.8
    if word in {'warn', 'warned', 'warns', 'caution', 'alarmed', 'vigilant'}:
        return 2.1
    if word == 'police':
        return 1.75
    for words, strength in ((VIGILANCE, 1.3), (SENSING, 1.0),
                            (PREVENTION, 0.8), (AWARENESS, 0.6)):
        if word in words or (word.endswith('s') and word[:-1] in words):
            return strength
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    text = raw.strip().lower()
    value = lexical(raw)
    if '\ufffd' in raw:
        value = CHINESE.get(prefix.text_prefixes[-1][-1:], 0.0)

    # Accumulate an English word across token boundaries.
    tail = re.search(r'[a-z]+$', text)
    word = tail.group() if tail else text
    if (raw[:1].isascii() and raw[:1].isalpha()
            and previous.isascii() and previous.isalpha()):
        word = previous + word
        if value == 0.0:
            value = 0.6 * lexical(word)

    if previous == 'early':
        value = {'warning': 7.2, 'detection': 3.7,
                 'diagnosis': 2.45}.get(text, value)
    if text == 'of':
        if previous in {'aware', 'afraid', 'danger', 'fear', 'warned'}:
            value = 0.8
        elif previous in {'risk', 'suspicion', 'awareness'}:
            value = 0.6
        elif previous in {'diagnosis', 'detection'}:
            value = 0.35
    elif text == 'about' and previous in {'worried', 'worry', 'concerned'}:
        value = 0.8
    elif text == 'to' and previous in {'sensitive', 'vulnerable', 'alert'}:
        value = 0.45
    elif previous == '警':
        value = {'报': 3.0, '報': 3.0, '戒': 6.5,
                 '觉': 2.3, '覺': 2.3}.get(text, value)
    return (doc, word[-40:]), float(value)

programs.luna:
"""Flag words for noticing, assessment, and risk or protection."""

READS = ()

NOTICE_STEMS = (
    "alert", "alarm", "warn", "notic", "notif", "watch", "detect",
    "monitor", "observ", "recogn", "sensitiv",
)
ASSESSMENT_STEMS = (
