programs.sol:
"""A sparse lexical approximation, especially the negative 'tiny' response.

'Tiny' gets a large negative value at document start. Code-like vocabulary
and punctuation weaken it; nearby physical/biological words strengthen it.
A few weaker word families, spelling endings and formatting markers are
also modeled. Most other token-specific fluctuations are left near zero.
Only a bounded 32-token history is retained, reset between documents.
"""
READS = ()

SCIENCE = frozenset('''
    atom atoms atomic electron electrons proton protons neutron neutrons
    molecule molecules molecular particle particles nuclear energy force
    hydrogen oxygen helium carbon metal metals chemical chemicals chemistry
    reaction reactions protein proteins cell cells dna rna gene genes light
    wavelength radiation semiconductor semiconductors quantum physics charge
    charged water air pressure temperature heat current voltage electricity
    electric magnetic field fields fluid gas surface
'''.split())
CODE_WORDS = frozenset('''
    int float double char const void return def class public private function
    var val null not default unsigned varchar table create select insert
    import include define struct typedef using namespace
'''.split())
SMALL_SCALE = frozenset('''
    small short low little mini micro thin compact narrow
'''.split())
METHODS = frozenset('method methods technique techniques'.split())
PAST_TIME = frozenset('first last already previously earlier later'.split())


def context(recent):
    words = [s.strip().lower() for s in recent]
    code = sum(w in CODE_WORDS or any(c in s for c in '{};_=`')
               for s, w in zip(recent, words))
    science = sum(w in SCIENCE for w in words)
    return min(code, 8) / 8, min(science, 6) / 6


def lexical_value(word):
    if word in SMALL_SCALE:
        return -0.034
    if word in METHODS:
        return -0.085
    if word.startswith('measur'):
        return -0.071
    if word.startswith('detect'):
        return -0.108
    if word in PAST_TIME:
        return -0.038
    if word == 'same':
        return -0.050
    if word == 'different':
        return 0.067
    return None


def background(token, word):
    if token == '<think>':
        return -0.188
    if token == '</think>':
        return 0.142
    if token.startswith('<|im_') or token.startswith('</tool_'):
        return -0.035
    if word in ('#', '##', '**', '•', '✓'):
        return -0.044
    value = -0.001
    if '\ufffd' in token:
        value -= 0.012
    elif word.isascii() and word.isalpha():
        if word.endswith(('tion', 'ment')):
            value += 0.009
        elif word.endswith('ly'):
            value += 0.006
        elif word.endswith(('ing', 'ed', 'al')):
            value -= 0.003
        elif len(word) > 3 and word.endswith('s'):
            value -= 0.003
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, recent = 0, ()
    else:
        position, recent = carry[1] + 1, carry[2]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    title = token.strip().istitle()
    no_space = not token.startswith(' ')
    if word == 'tiny':
        code, science = context(recent)
        value = -0.231 - 0.82 / (position + 1) ** 1.5
        value += 0.019 * title + 0.060 * no_space
        value += 0.159 * code - 0.287 * science
        if position == 0:
            if title:
                value = -1.120 if no_space else -1.065
            else:
                value = -0.704 if no_space else -0.967
        value = min(value, 0.0)
    else:
        value = lexical_value(word)
        if value is None:
            value = background(token, word)
        else:
            code, science = context(recent)
            gain = 1.02 - 0.58 * code + 1.17 * science
            gain -= 0.28 * no_space + 0.08 * title
            value *= max(0.2, gain)
    recent = (recent + (token,))[-32:]
    return (doc, position, recent), float(value)

"""Detect sw-initial words and a few related motion/manner word families.

The spelling sw is the main signal, not the topic of the surrounding text:
switch/swap/swift are strongest; swimming, Swedish and sweet are weaker.
Additional responses cover smoothness, speed, twisting and Chinese equivalents.
A recognized word split across tokens gives a reduced continuation response.
Completed byte fragments of Greek tonos vowels get a negative response.
Other tokens get zero. State is only the preceding fragment, reset per document.
"""
import unicodedata

READS = ()
LEADING = " \t\r\n._/-'\"(<"

# Prefix families, in priority order: inflections share a family.
SW_FAMILIES = (
    (3.3, ('switch', 'swap', 'swift', 'swipe')),
    (2.5, ('swim', 'swear', 'sworn', 'swore', 'swoll', 'swelling')),
    (2.3, ('swing', 'swung', 'swed', 'swallow')),
    (2.0, ('swiss', 'switz', 'sweet')),
    (1.6, ('swell',)),
    (0.65, ('swer', 'sworth', 'swick')),
    (0.35, ('sword',)),
    (1.3, ('sweep', 'swept', 'swamp', 'swo', 'swirl')),
