    (0.78, ('smart', 'wise')),
    (0.7, ('dance', 'dancing', 'dancer', 'dancers', 'dances', 'danced')),
    (0.55, ('flip', 'flipped', 'flipping', 'slide', 'slides', 'sliding', 'slider')),
    (0.4, ('exchange', 'exchanges', 'exchanged', 'rotating', 'rapidly')),
    (0.85, ('spinning', 'speedy', 'schw', 'zw', 'св')),
    (0.65, ('span', 'spans', 'spanish', 'spain')),
    (2.4, ('舞', '交换')),                         # dance; exchange/swap
    (1.5, ('开关', '切换', '泳', '游泳', '瑞士')),   # switch; swim; Swiss
    # Change, sliding, sweetness, twisting, swiftness.
    (0.87, ('换', '換', '滑', '甜', '扭', '迅速')),
    (0.52, ('转换',)),                            # conversion/switching
