    low = word.lower()
    if low.startswith('sw') and not word.startswith('sW'):
        if low == 'sw':
            if word == 'SW':
                return 2.9
            if token == 'sw':
                return 3.65
            return 4.1 if word == 'Sw' else 4.3
        if low == 'switch':
            if token == 'switch':
                return 4.4
            return 3.1 if token == ' Switch' else 3.8
        if low.startswith('switch'):
            return 3.15
        if low == 'swan':
            return 2.6
        if low in ('swiftly', 'swaps', 'sweets', 'sweetness'):
            if low == 'swiftly':
                return 2.3
            return 2.6 if low == 'swaps' else 0.95
        for value, roots in SW_FAMILIES:
            if low.startswith(roots):
