        return 1.0
    if low.startswith('smooth'):
        derived = token.startswith('_') or low in ('smoothing', 'smoother')
        return 0.7 if derived else 1.5
    if low.startswith('smith'):
        return 0.6 if token == ' smith' else 0.9
    if low.startswith('quick'):
        return 1.03 if low == 'quickly' else 0.72
    if low.startswith('slow'):
        return 0.87 if low == 'slow' else 0.6
    if low.startswith(('twist', 'twitch')):
        return 1.25 if low in ('twisting', 'twisted') else 1.0
    if low == 'tw':
        return 0.85 if word == 'Tw' else 0.4
    for value, words in ASSOCIATES:
        if low in words:
