    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    value = strength(token)
    # A byte fragment may complete a Greek vowel with a tonos accent.
    if '\ufffd' in token:
        text = prefix.text_prefixes[-1]
        char = text[-1:]
        name = unicodedata.name(char, '') if char else ''
        if 'GREEK' in name and 'WITH TONOS' in name:
            value = -2.0 if char.isupper() else -1.0
    if previous and token and token[0].isalpha():
        joined = previous + token.lower()
        if previous == 's' and token.lower().startswith('witch'):
            value = max(value, 2.8)
        elif previous == 'switch' and token.lower() in ('ed', 'ing', 'es'):
            value = max(value, 1.5 if token.lower() == 'es' else 2.0)
        elif previous == 'sw' and joined.startswith('swimm'):
            value = max(value, 2.1)
        elif joined.startswith(('swap', 'swallow', 'swing', 'swiss')):
            value = max(value, 0.55 * strength(joined))
    low = token.lstrip(LEADING).lower()
    previous = low if low == 's' or low.startswith('sw') else ''
    return (doc, previous), float(value)

