"""Activation of layers.0.mlp.down_proj:4274: a "switch / sw-word" detector.

It reads only the current token (the word it spells out, lowercased, with leading
punctuation such as "/" or " " dropped) and reports how strongly that token belongs to
the family of words it responds to:

- the fragment "sw" (3.8) and "switch" (3.6), "swap"/"swift"/"swipe" and their forms (3.2):
  strongest;
- other "sw..." words (swim, sweet, swing, Sweden): moderate, about 2;
- "sword"-type words: about 0.8;
- words of turning, swapping and exchange (twist, flip, spin, dance, exchange, and the
  Chinese for switch and exchange, 开关 切换 交换 换): about 0.5;
- words of speed and smoothness (quick, slow, smooth, smart, speedy, 迅速 滑): about 0.75;
- everything else is 0.

Why: at layer 0 the MLP output is mostly a function of the token itself, and this
component writes a large "switch" signal into the residual stream when the token starts a
switch-like word. Most of its variance is in the sw family; the rest is a diffuse
motion/speed/swap sensitivity, which the small word sets capture in part.
"""

import re

READS = ()

SWITCH_FORMS = re.compile(r"sw(itch|ap|ift|ipe)")
TURN_WORDS = {
    "twist", "twisting", "twists", "flip", "flipping", "spin", "spinning", "spun",
    "toggle", "exchange", "exchanges", "rotate", "rotating", "wipe", "whisk",
    "dance", "dancing", "dances", "danced",
}
TURN_CHARS = set("开关切换交换换转扭舞")
SPEED_WORDS = {
    "quick", "quickly", "quicker", "slow", "slowly", "slower", "smooth", "smoothly",
    "smart", "speedy", "steady", "seamless", "sleek",
}
SPEED_CHARS = set("迅速快速滑慢")


def word(token: str) -> str:
    """The token's letters (or Chinese characters), lowercased, without leading punctuation."""
    return re.sub(r"^[^a-z一-鿿]+", "", token.strip().lower())


def activation(token: str) -> float:
    w = word(token)
    if w == "sw":
        return 3.8
    if w.startswith("switch"):
        return 3.6
    if SWITCH_FORMS.match(w):
        return 3.2
    if w.startswith("swo"):
        return 0.8
    if w.startswith("sw"):
        return 2.0
    if w in TURN_WORDS or (len(w) == 1 and w in TURN_CHARS):
        return 0.5
    if w in SPEED_WORDS or (len(w) == 1 and w in SPEED_CHARS):
        return 0.75
    return 0.0


def step(carry, prefix, upstream):
    """Predict this component's activation at the newest token."""
    return None, float(activation(prefix.token_strings[-1]))

