programs.sol:
"""A word-fragment continuation signal, usually negative inside a split word.

Spaces, punctuation and changes of script usually start a new word. Capital
letters in camelCase also suggest a new word. Short chunks in unspaced scripts
are more likely to be fragments than whole words. The numeric strengths are
estimates from training text, not a dictionary of individual vocabulary items.
Partial Unicode characters have a weaker fallback signal. Conversation
boundary tags are a separate negative signal.
"""
import unicodedata

READS = ()


def script(c):
    if c == 'ー':
        return 'KATAKANA'  # Japanese long-vowel mark.
    if not c.isalpha():
        return ''
    name = unicodedata.name(c, '')
    for group in ('LATIN', 'CYRILLIC', 'GREEK', 'ARABIC', 'HEBREW',
                  'HIRAGANA', 'KATAKANA', 'HANGUL', 'THAI'):
        if group in name:
            return group
    return 'HAN' if 'CJK' in name or 'IDEOGRAPH' in name else ''


def continuation(previous, token, group):
    n, m = len(token), len(previous.strip())
    a, b = previous[-1], token[0]
    if group in ('LATIN', 'CYRILLIC'):
        if a.islower() and b.isupper():
            # Capitalization separates words in camelCase identifiers.
            return -0.4 if n <= 2 else (-0.2 if n <= 4 else -0.03)
        if a.isupper() and b.islower():
            return -0.65 if n == 1 else (-1.1 if n == 2 else -1.25)
        if a.isupper() and b.isupper():
            if token.istitle() and n > 1:
                return -0.9
            return -1.3 if m == 1 else -1.55
        value = -1.52
        value += 0.18 if n == 1 else 0.09 * min(4, max(0, n - 4))
        value += 0.25 if m == 1 else (0.1 if m == 2 else 0.0)
        value -= 0.08 if previous.strip().istitle() else 0.0
        value -= 0.06 if b.lower() in 'aeiou' else 0.0
        return value
    if group == 'HAN':
        return -0.56 if n == m == 1 else (-0.16 if n == 1 and m == 2 else -0.04)
    if group == 'HIRAGANA':
        return -0.85 / (n * max(1, m))
    if group == 'HANGUL':
        return (-0.95 if n == 1 else -0.35) * (0.5 if m > 2 else 1.0)
    if group == 'THAI':
        return -0.64
    return -1.2


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    value = -0.01
    if token and previous:
        a, b = previous[-1], token[0]
        sa, sb = script(a), script(b)
        if sa and sa == sb and not previous.endswith(('\\n', '\\t', '\\r')):
            value = continuation(previous, token, sb)
        # Byte fragments obscure the writing system, so use a weaker estimate.
        if a == '\ufffd':
            if b == '\ufffd':
                value = -0.45
            elif sb:
                value = -0.75
        elif b == '\ufffd' and sa == 'HAN':
            value = -0.60
    elif token and token[0].islower():
        value = -0.5  # A row can begin in the middle of a word.

    if token == '<|im_start|>':
        value = -1.05 if previous else -0.6
    elif token == '<|im_end|>':
        value = -0.55
    elif token in ('<tool_call>', '</tool_call>'):
        value = -1.45
    elif token == '<tool_response>':
        value = -1.25
    elif token == '</tool_response>':
        value = -0.6
    return (doc, token), float(value)

"""Detect leading digits and line-initial list markers, not whole numbers.

An ASCII digit after whitespace is strongest at the beginning of a line. Indentation
and another recently written number weaken it; sentence-ending punctuation
strengthens it. Digits within an unspaced number have almost no response.
Zero is weaker than other leading digits, while one and two are stronger.
Early alphabetic labels, Roman numerals, and Q also get a small line-start
response. Selected Chinese, fullwidth, superscript and subscript numeral
forms receive fixed responses. The state resets between documents.
"""
from math import exp

READS = ()
LINE_MARKERS = {
    '-': 0.69, '+': 0.41, '*': 0.46,
    '○': 1.03, '・': 0.67, '•': 0.06,
}
SENTENCE_ENDS = frozenset('.!?。！？')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', True, 0, 100, 100, False)
    _, previous, nonspace, blank, line_tokens, char_gap, token_gap, seen = carry
    token = prefix.token_strings[-1]
    value = 0.0

    if len(token) == 1 and token in '0123456789':
        digit = int(token)
        zero = digit == 0
        small = digit in (1, 2)
        if not seen:
            value = 0.62 if small else 0.02
        elif previous.isdigit():
            value = 0.0 if zero else -0.025
        elif previous.isspace() and blank:
            indented = previous != '\n'
            recent = exp(-token_gap / 10)
            value = 1.42 - 0.43 * indented - 0.40 * recent
            value += 0.23 * (nonspace in SENTENCE_ENDS)
            if zero:
                value += -0.62 - 0.09 * indented + 0.20 * recent
            elif small:
                value += 0.19 - 0.04 * indented
        elif previous.isspace():
            recent = exp(-char_gap / 30)
            value = 0.42 - 0.30 * recent
            value += 0.14 * nonspace.isalpha()
            value += 0.22 * (nonspace in SENTENCE_ENDS)
            value -= 0.06 * nonspace.isdigit()
            if zero:
                value += -0.26 + 0.22 * recent
            elif small:
                value += 0.14 + 0.08 * nonspace.isalpha()
            elif digit == 3:
                value += 0.04
        else:
            value = 0.04 - 0.10 * exp(-char_gap / 10)
            value += 0.13 * (line_tokens <= 1)
            value -= 0.015 * nonspace.isalpha()
    elif token in LINE_MARKERS:
        value = LINE_MARKERS[token] if seen and blank else 0.02
    elif token in (' -', ' *', ' +'):
        if blank:
            value = {' -': 0.46, ' *': 0.15, ' +': 0.28}[token]
        elif previous.isspace() and token == ' -':
            value = 0.28
    elif token == '-\n' and blank:
        value = 0.29
    elif token == '+\n' and blank:
        value = 0.08
    elif blank and seen and token.strip().lower() in ('a', 'b', 'c', 'd'):
        label = token.strip().lower()
        value = 0.2 if label in ('a', 'b') else 0.1
    elif blank and seen and token in ('II', 'III', 'IV', 'ii', 'iii', 'iv'):
        value = 0.45
    elif blank and seen and token == 'Q':
        value = 0.45
    elif token in ('¹', '²', '³', '₁', '₂', '₃'):
        value = 0.2
    elif token in ('一', '二', '三', '四', '五', '第一', '第二'):
        value = 0.9 if blank and seen else 0.15
    elif len(token) == 1 and '０' <= token <= '９':
        value = 1.1 if blank and seen else 0.4

    line_tokens += 1
    token_gap = min(token_gap + 1, 100)
    for char in token:
        char_gap = min(char_gap + 1, 100)
        if char.isdigit():
            char_gap = token_gap = 0
        if char == '\n':
            blank = True
            line_tokens = 0
        elif not char.isspace():
            blank = False
        if not char.isspace():
            nonspace = char
        previous = char
    return (doc, previous, nonspace, blank, line_tokens,
            char_gap, token_gap, True), float(value)

