"""Estimate a signal for number starts, line markers, and Chinese ordinals."""

READS = ()


CHINESE_LIST_ORDINALS = frozenset(
    "第一 第二 第三 第四 第五 第六 第七 第八 第九 第十".split()
)

LINE_START_MARKS = {"-": 0.75, "+": 0.60}

NUMBER_ESTIMATES = {
    "0": 0.20,
    "1": 0.71,
    "2": 0.70,
    "3": 0.63,
    "4": 0.55,
    "5": 0.54,
    "6": 0.54,
    "7": 0.54,
    "8": 0.54,
    "9": 0.54,
}


def step(carry, prefix, upstream):
    """Highlight number starts, ordinal labels, and line-start dash or plus markers."""
    text = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if carry is None:
        line_blank, old_document = False, document
    else:
        line_blank, old_document = carry
        if document != old_document:
            line_blank = True

    value = 0.0
    if text in NUMBER_ESTIMATES and prefix.position > 0:
        if document == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
            if previous and previous[-1].isspace():
                value = NUMBER_ESTIMATES[text]
            elif previous and previous[-1].isnumeric():
                value = -0.02
    elif text in LINE_START_MARKS and line_blank:
        value = LINE_START_MARKS[text]
    elif text in CHINESE_LIST_ORDINALS and line_blank:
        value = 1.70

    if "\n" in text:
        tail = text.rsplit("\n", 1)[-1]
        next_line_blank = all(char.isspace() for char in tail)
    else:
        next_line_blank = line_blank and all(char.isspace() for char in text)
    return (next_line_blank, document), value

"""Predict negative activations for words about means and methods.

Strong examples include “means” and “methods”; “way” and manner words are
usually weaker, while “of” can be strong after “means,” “way,” or “form.”
The small word groups encode those rough differences in strength, along with
sampled page-break and multilingual cues; they are not a full context model.
"""

READS = ()

STRONG_METHOD_WORDS = {"means", "method", "methods"}
WAY_WORDS = {"way", "mode", "route", "pathway", "procedure", "mechanism"}
MANNER_WORDS = {"directly", "easily", "依靠", "很容易", "удоб", "удобный"}
OTHER_WAY_WORDS = {"机制", "法", "作弊", "แบบ"}
OF_PHRASE_HEADS = {"mean", "means", "way", "form"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    if raw == "\f":
        return None, -0.5

    word = raw.strip().casefold()
    if word in STRONG_METHOD_WORDS:
        return None, -1.5
    if word.startswith("meth"):
        return None, -1.2
    if word in WAY_WORDS or word.endswith("mode"):
        return None, -0.9
    if word in MANNER_WORDS or word in OTHER_WAY_WORDS:
        return None, -0.7
    if word == "meant":
        return None, -0.9
    if word == "mean" or "mean" in word:
        return None, -0.7

    if word == "of" and len(prefix) > 1:
        same_document = prefix.document_ids[-1] == prefix.document_ids[-2]
        previous = prefix.token_strings[-2].strip().casefold()
        if same_document and previous in OF_PHRASE_HEADS:
            return None, -1.2

    return None, 0.0

