"""Detect the account word family and its immediate grammatical continuations.

Account/accounted/accounts/accounting give the large response; 'into account'
and 'bank account' are weaker. Suffixes and following 'for' or 'of' continue
it. Smaller signals recognize multilingual account words, accountability,
allowance, responsibility, and common '... for' constructions. Otherwise zero.
Only the last 64 text characters are carried, with a reset for each document.
"""
import re

READS = ()
ACCOUNTS = {'account', 'accounts', 'accounted', 'accounting'}
FOR_COMPLEMENTS = {}
for words, strength in [
    ('account accounts', 3.8),
    ('accounted accounting', 4.8),
    ('accountable', 2.4),
    ('responsible allow allows allowing allowance', 2.0),
    ('allowed solve explanation explanations', 1.45),
    ('adjust adjusts adjusted adjusting compensate', 1.35),
    ('solving solved liable blamed', 1.1),
    ('provide provides make makes', 0.95),
    ('reason reasons cause except save thanks apologize', 0.75),
    ('ask asks suitable treatment compensation responsibility pay', 0.6),
]:
    FOR_COMPLEMENTS.update(dict.fromkeys(words.split(), strength))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    match = re.search(r'[A-Za-z]+$', tail.rstrip())
    previous = match.group().lower() if match else ''
    bare = word.lstrip('._-/(<')
    value = 0.0
    if bare in ACCOUNTS:
        value = 6.2 if token.startswith(' ') else 5.5
        if bare == 'accounting':
            value = 4.4 if token.strip()[:1].isupper() else 5.3
        if bare == 'account' and previous in {'into', 'taking', 'bank', 'on'}:
            value = 5.3 if previous == 'on' else 4.0
    elif 'account' in word and word.endswith(('account', 'accountid')):
        value = 3.8
    elif bare in {'accountable', 'accountability', 'accountant', 'accountants'}:
        value = 1.85
    elif (not token[:1].isspace() and previous == 'account'
          and word in {'ing', 's', 'ed', 'ings', 'ant', 'ants', 'able', 'ability'}):
        if word in {'ing', 's', 'ed', 'ings'}:
            value = 3.7
        elif word in {'ant', 'ants', 'able', 'ability'}:
            value = 1.2
    elif not token[:1].isspace() and previous == 'a' and word == 'ccount':
        value = 3.3
    elif word in {'账', '帐', '帳', '账户', '账号', '帐号', '帳號'}:
        value = 2.6
    elif word in {'учет', 'cuenta', 'cuent', 'compte'}:
        value = 1.25
    elif word in {'счет', 'conta', 'compt'}:
        value = 0.55
    elif word in {'allowance', 'allowances'}:
        value = 1.75
    elif word in {'responsible', 'respons'}:
        value = 0.6
    elif word in {'accommodate', 'accommod'}:
        value = 1.1
    elif word == 'for':
        value = FOR_COMPLEMENTS.get(previous, 0.0)
        if previous not in ACCOUNTS and token.strip() != 'for':
            value = 0.45 if token.strip() == 'FOR' else 0.11
    elif word == 'of' and previous in ACCOUNTS:
        value = 2.7
    return (doc, (tail + token)[-64:]), value

