    '</tool_response>': -2.14,
    '</tool_call>': -1.45,
    '<tool_response>': -1.10,
}


def token_value(token):
    word = token.strip()
    lower = word.lower()
    if word in TOOL_MARKUP:
        return TOOL_MARKUP[word]
    if '✓' in word or '✔' in word:
        return -0.88
    if lower in {'after', 'afterwards'}:
        return -0.88
    if lower in LEGAL_LINKS:
        return -1.0
    if lower in PRAISE:
        return -0.77
    if lower in BENEFITS:
        return -0.80
    if lower in GENERALITY:
        return -0.60
    if lower in KINSHIP:
        return -0.64
    if lower in PLATFORMS:
        return -0.60
    if lower in {'quite', 'rather'}:
        return 0.65
    if lower in {'release', 'released', 'releases', 'releasing'}:
        return 1.33
    if lower in {'resolve', 'resolved', 'resolves', 'resolving',
                 'resolution', 'resolver'}:
        return 0.68
    if lower in {'expose', 'exposed', 'exposure', 'emission', 'emissions'}:
        return 0.63
    if lower in SALIENCE:
        return 0.60
    if lower in {'rest', 'rests', 'rested', 'resting'}:
        return -0.68
    if lower in {'pattern', 'patterns', 'patterned', 'patterning'}:
        return -0.68
    if lower in PEOPLE:
        return 0.19
    if word.istitle() and lower in GIVEN_NAMES:
        return -0.34
    if lower in {'high', 'low'}:
        return -0.25
    if lower == 'extra':
        return -0.65
    if lower == 'upon':
        return -0.54
    if word.startswith('\\x') and len(word) > 2:
        if all(c in '0123456789abcdefABCDEF' for c in word[2:]):
            return -0.46
    if '\ufffd' in word:
        return -0.18 if token[0].isspace() else -0.36
    # Hangul syllables.
    if any('\uac00' <= c <= '\ud7af' for c in word):
        return -0.33 if token[0].isspace() else -0.14
    # CJK ideographs.
    if any('\u4e00' <= c <= '\u9fff' for c in word):
        return -0.10
    # Japanese hiragana and katakana.
    if any('\u3040' <= c <= '\u30ff' for c in word):
        return -0.065 * min(len(word), 4)
    # Arabic script.
    if any('\u0600' <= c <= '\u06ff' for c in word):
        return -0.08 * max(0, min(len(word), 4) - 1)
    # Cyrillic: initial word pieces differ from continuation pieces.
    if any('\u0400' <= c <= '\u052f' for c in word):
        if token[0].isspace():
            return -0.03 * max(0, min(len(word), 7) - 1)
        return 0.0
    if word.isalpha():
        value = -0.012 * max(0, min(len(word), 8) - 3)
        if word.istitle() and len(word) > 3:
            value -= 0.025
        if lower.endswith(('ing', 'ly', 'ity', 'tion', 'ful')):
            value += 0.09
        elif lower.endswith(('ed', 'al', 'ment', 'able')):
            value += 0.05
        value -= 0.03 * sum(c in lower for c in 'jkqxz')
        return value
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    position = 0 if carry is None or carry[0] != document else carry[1] + 1
    value = token_value(prefix.token_strings[-1])
    if position == 0:
        value += 0.04
    return (document, position), float(value)

programs.haiku:
"""Layer-0 MLP down_proj component 4279, a rough token-class sketch.

The component is mostly quiet (median near 0). Its large values are token-specific and come
from a long tail of tokens, so no short list captures much of it. This program predicts the
activation from the current token's text alone:

- tool-call tags such as </tool_response> and </tool_call> are strongly negative (about -1.2);
- words built on "release" or "resolve" are positive (about +1.0);
- partial UTF-8 bytes (a character split across tokens) are mildly negative (about -0.35);
- CJK, kana and hangul characters are slightly negative (about -0.12);
- capitalised English words (names, titles) are slightly negative (about -0.10);
- everything else is predicted as 0.
"""

import re
import unicodedata

READS = ()

TOOL_TAG = re.compile(r"</?tool_(response|call)>")
RELEASE_RESOLVE = re.compile(r"(?i)re(lease|solv|solu)")
CAP_WORD = re.compile(r" [A-Z][a-z]+")
SCRIPT_PREFIXES = ("CJK", "HIRAGANA", "KATAKANA", "HANGUL")


def is_cjk(text):
    return any(unicodedata.name(c, "").startswith(SCRIPT_PREFIXES) for c in text)


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    if TOOL_TAG.fullmatch(text):
        value = -1.2
    elif RELEASE_RESOLVE.search(text):
        value = 1.0
    elif "�" in text:
        value = -0.35
    elif is_cjk(text):
        value = -0.12
    elif CAP_WORD.fullmatch(text):
        value = -0.1
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Approximate the activation from the visible shape of the current token.

The strongest cues are tool-message boundary markers and closing tags. Token
length, punctuation, and a few common English word beginnings/endings provide
smaller adjustments; this is a compact surface heuristic, not a token lookup.
"""

READS = ()

PREFIX_WEIGHTS = (
    ("anti", -0.233),
    ("over", 0.211),
    ("inter", 0.182),
    ("pre", 0.087),
    ("un", 0.032),
)

SUFFIX_WEIGHTS = (
    ("ity", 0.108),
    ("tion", 0.095),
    ("ness", -0.076),
    ("sion", 0.070),
    ("ed", 0.072),
    ("ing", 0.063),
    ("ive", 0.057),
    ("ly", 0.052),
    ("ic", 0.034),
    ("ous", 0.026),
    ("er", -0.032),
    ("ment", 0.025),
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    letters = [char for char in text if char.isalpha()]
    word = "".join(letters).lower()
    score = -0.0062 - 0.0166 * min(len(text), 16)

    if len(text) >= 7:
        score += 0.0209
    if text and len(letters) == len(text):
        score -= 0.0096
    if any(not char.isalnum() for char in text):
        score -= 0.129
    if any(ord(char) > 127 for char in text):
        score -= 0.046
    if "\ufffd" in text:
        score -= 0.304
    if text and text[0].islower():
        score += 0.057
    if text and text[0].isupper():
        score -= 0.016
    if letters and all(char.isupper() for char in letters):
        score += 0.047
    if "<" in text or ">" in text:
        score += 0.032
    if "<|" in text and "|>" in text:
        score += 0.030
    if "tool" in text.lower() and ("<" in text or ">" in text):
        score -= 0.398
    if text.startswith("</") and text.endswith(">"):
        score -= 1.156
    if "_" in text:
        score -= 0.032
    if text and not text[0].isalnum():
        score += 0.151

    for beginning, weight in PREFIX_WEIGHTS:
        if word.startswith(beginning):
            score += weight
    for ending, weight in SUFFIX_WEIGHTS:
        if word.endswith(ending):
            score += weight

    return carry, float(score)

"""Recognize ease, ease-of-action words, and their common translations."""

READS = ()


def step(carry, prefix, upstream):
    """Pulse on ease-related words, plus the 'to' in 'easy to ...'."""
    word = prefix.token_strings[-1].lstrip().lower()

    if word.startswith(("easy", "easi", "ease")):
        return None, -1.35
    if word.startswith("readily"):
        return None, -1.15
    if word.startswith("effortless"):
        return None, -0.6
    if "susceptib" in word:
        return None, -1.0

    if "容易" in word:
        return None, -3.5
    if "易" in word:
        return None, -3.0
    if "难" in word:
        return None, -1.0
    if any(form in word for form in ("やす", "にくい")):
        return None, -1.2
    if "簡単" in word:
        return None, -0.8
    if "легко" in word:
        return None, -1.2
    if "leicht" in word:
        return None, -0.8
    if word.startswith("すぐに"):
        return None, -0.55

    # The word after easy/easier is also a strong cue in the phrase "easy to".
    if (word == "to" and len(prefix.token_strings) > 1
            and prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2].lstrip().lower()
        if previous.startswith(("easy", "easi", "ease")):
            return None, -1.15

    return None, 0.0

"""Small positive cues for technical word forms, measurement units, and legal boilerplate.
"""
import unicodedata

READS = ()

UNITS = {
    "wt", "ph", "rpm", "hz", "khz", "mhz", "ift", "dna", "rna", "co2",
}
LEGAL_TERMS = {"herein", "hereby", "thereof", "whereof", "hereto"}
TECHNICAL_ENDINGS = (
    "tion", "sion", "ity", "ical", "ology", "genic", "lysis", "ase",
    "meter", "metric", "graph", "scope", "thermal", "longitudinal",
    "ial", "ous", "ive", "ized", "ization", "atory", "threshold",
    "ium", "ide", "ate", "able", "icle", "ents",
)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        current, previous = "", ""
    else:
        _, current, previous = carry

    # Join byte-piece tokens into the word seen so far; discard it at spaces
    # and punctuation. This lets a recognizable ending span several tokens.
    for char in prefix.token_strings[-1]:
        category = unicodedata.category(char)
        if char.isalpha() or char.isdigit() or category.startswith("M"):
            current += char
        else:
            if current:
                previous = current.lower()
            current = ""

    word = current.lower()
    score = 0.0
    if word in UNITS or previous in UNITS and prefix.token_strings[-1].strip() in {"%", "‰"}:
        score = 0.03
    elif word in LEGAL_TERMS:
        score = 0.021
    elif any(word.endswith(ending) for ending in TECHNICAL_ENDINGS):
        score = 0.021

    return (document, current, previous), float(score)

programs.sol:
"""Predict a negative, mainly lexical FACT-family signal.

'Fact' is strongest; facts/factual, factory, practice, actual, and a few
translations are weaker. Root fragments explain split words. This does
not decide whether text is true. The short word tail resets per document.
"""
import re

READS = ()

# Full words about facts, reality, practice, and making.
WORD_SIGNALS = {
    'fact': -6.25, 'facts': -4.8, 'factual': -3.1,
    'factor': -1.0, 'factors': -0.65, 'factorial': -1.25,
    'actually': -0.98, 'actual': -0.28,
    'practice': -1.7, 'practices': -1.4, 'practiced': -1.25,
    'practise': -0.96, 'practicing': -0.9,
    'truth': -0.4, 'reality': -1.05, 'realities': -0.75,
    'fakt': -2.0, 'факт': -1.8, 'фак': -1.8, 'facto': -2.2,
    'fait': -0.73, 'fatto': -1.0, 'hecho': -1.3,
    'thật': -0.6, '사실': -2.8,
    '工厂': -1.8, '工廠': -1.8, '制造': -1.8, '製造': -1.8,
    '厂': -1.9, '廠': -2.0, '造': -0.85, '生产': -0.65, '生產': -0.65,
    '实践': -0.8, '實踐': -0.8, '事': -1.3,
    '真相': -1.0, '实际上': -1.2, '實際上': -1.2,
}
ROOT_FRAGMENTS = {'fac': -1.1, 'fa': -0.5, 'pract': -1.0,
                  'ufact': -1.4, 'actice': -1.7}


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    word = token.strip().lstrip('_.').lower()
    match = re.search(r'[a-z]+$', (previous + token.lower())[-48:])
    joined = match.group() if match else ''
    value = WORD_SIGNALS.get(word, ROOT_FRAGMENTS.get(word, 0.0))
    if word == 'fact' and token.strip().lstrip('_.')[0].isupper():
        value = -5.8
    if word in {'fact', 'facts'} and joined.startswith('artefact'):
        value = -1.7 if word == 'fact' else -1.1
    elif word == 'actual' and joined.endswith('factual'):
        value = -1.55
    elif word in {'factory', 'factories'} or token.endswith('Factory'):
        value = -4.05 if token == 'Factory' else -2.6
        if joined.endswith('olfactory'):
            value = -0.85
    elif word.startswith('manufact'):
        value = -0.55 if 'manufacturer' in word else -1.2
    elif token == 'act':
        value = -0.5
        if joined.endswith('surfact'):
            value = -2.4
        elif joined.endswith(('pract', 'refact', 'transact', 'lact')):
            value = -1.6
        elif joined.endswith('fact'):
            value = -1.8
    elif token == 'acts' and joined == 'facts':
        value = -4.5
    elif token in {'actory', 'actor'} and joined.endswith(('factory', 'factor')):
        value = -1.9 if token == 'actory' else -1.25
    elif '事实' in word or '事實' in word:
        value = -4.6 if word.endswith('上') else -5.5
    if word == 's' and previous == 'fact':
        value = -2.2
    elif word == 'that' and previous == 'fact':
        value = -0.95
    elif word == 'of' and previous in {'facts', 'practice', 'factorial'}:
        value = -1.6 if previous == 'facts' else -0.4
    elif word == 'the' and previous == 'fact':
        value = -0.36
    return (doc, joined), float(value)

