programs.sol:
"""A punctuation-conditioned response to numeric and programming continuations.

A zero after a dot (decimals and versions) is the main trigger. Repeated spaced
periods, dotted file suffixes and common member operations also trigger it.
Separate rules cover code-fence labels, PHP opening tags and URL schemes.
All rules use only this token and the preceding token in the same document.
"""
READS = ()

STRING_FORMATTING = {'join', 'format'}
SEQUENCE_OPERATIONS = {
    'append', 'into', 'trim', 'split', 'strip', 'reshape', 'repeat',
    'length', 'keys', 'get', 'map', 'collect', 'unwrap', 'then', 'equals',
}
MEMBER_OPERATIONS = {
    'add', 'set', 'toString', 'lower', 'replace', 'items', 'filter',
    'text', 'find', 'create', 'name', 'size', 'test', 'grid', 'path',
    'send', 'show', 'catch', 'on', 'forEach', 'iterator', 'values',
    'addGroup', 'addGap', 'indexOf', 'toFixed', 'getBytes',
}
PYTHON_PHP_DOTNET = {'py', 'php', 'NET'}
FILE_SUFFIXES = {
    'git', 'html', 'java', 'js', 'com', 'zip', 'png', 'jpg',
    'txt', 'csv', 'json', 'css', 'xml', 'yaml', 'pdf', 'doc', 'xlsx',
    'exe', 'jar', 'svg', 'gif', 'woff', 'lua',
}
SHORT_CODE_FILE_MARKERS = {'go', 'ts', 'h', 'env', 'github'}
LANGUAGES = {
    'python', 'cpp', 'c', 'js', 'javascript', 'typescript', 'html',
    'xml', 'json', 'php', 'bash', 'java', 'ruby', 'css', 'sql',
}
DOT_DIGITS = (2.34, -0.08, -0.17, -0.19, -0.03,
              0.28, 0.04, 0.03, 0.07, 0.34)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if previous.endswith('.'):
        if len(token) == 1 and token in '0123456789':
            value = DOT_DIGITS[int(token)]
            if token == '0' and previous == ' .':
                value = 2.6
        elif token == ' .':
            if previous == ' .':
                value = 3.5
            elif previous == '.':
                value = 2.95
            else:
                value = 1.5
        elif token in PYTHON_PHP_DOTNET:
            value = 4.9
        elif token in FILE_SUFFIXES:
            value = 3.8
        elif token in SHORT_CODE_FILE_MARKERS:
            value = 2.3
        elif token in STRING_FORMATTING:
            value = 4.3 if previous.endswith(("'.", '".')) else 3.1
        elif token in SEQUENCE_OPERATIONS:
            value = 2.2
        elif (token in MEMBER_OPERATIONS or
              (token.startswith('to') and len(token) > 2 and token[2].isupper())):
            value = 1.8
        elif token.isascii() and token.isidentifier():
            value = 0.65
    elif not previous and token == ' .':
        value = 4.0
    elif previous.endswith('```') and token.strip() in LANGUAGES:
        value = 2.0
    elif previous.endswith('<?') and token == 'php':
        value = 4.9
    if token.strip() == 'https':
        value = 0.58
    elif token.strip() == 'http':
        value = 0.46
    elif token == 'www':
        value = 0.32
    return (doc, token), value

